const _gavURLCache = Object.create(null);
function groupAvatarImageURL(c, cb) {
  const done = (typeof cb === 'function') ? cb : function () {};
  if (!c) { done(''); return; }
  if (c.kind !== 'group') { done(chatAvatarOf(c) || ''); return; }
  if (c.avatar) { done(c.avatar); return; }
  const names = (c.members || []).slice(0, 4);
  const srcs = names.map(n => {
    const m = (data.contacts || []).find(x => x.kind !== 'group' && x.name === n);
    return (m && chatAvatarOf(m)) || '';
  });
  if (!srcs.some(Boolean) || typeof document === 'undefined') { done(''); return; }
  const key = String(c.id || '') + '#' + srcs.join('|');
  if (_gavURLCache[key]) { done(_gavURLCache[key]); return; }
  let cv = null, g2 = null;
  try {
    cv = document.createElement('canvas');
    cv.width = 192; cv.height = 192;
    g2 = cv.getContext('2d');
  } catch (e) { cv = null; }
  if (!cv || !g2) { done(''); return; }
  g2.fillStyle = '#ffffff';
  g2.fillRect(0, 0, 192, 192);
  const half = 96;
  const box = i => (srcs.length === 1
    ? [0, 0, 192, 192]
    : ([[0, 0, half, half], [half, 0, half, half], [0, half, half, half], [half, half, half, half]][i] || [0, 0, half, half]));
  let left = srcs.length, drew = false;
  const finish = () => {
    if (--left > 0) return;
    if (!drew) { done(''); return; }
    try {
      const url = cv.toDataURL('image/png');
      _gavURLCache[key] = url;
      done(url);
    } catch (e) { done(''); }
  };
  srcs.forEach((src, i) => {
    if (!src) { finish(); return; }
    const img = new Image();
    img.onload = () => {
      try {
        const [x, y, w, h] = box(i);
        const s = Math.max(w / (img.width || w), h / (img.height || h));
        const dw = (img.width || w) * s, dh = (img.height || h) * s;
        g2.save();
        g2.beginPath();
        g2.rect(x, y, w, h);
        g2.clip();
        g2.drawImage(img, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
        g2.restore();
        drew = true;
      } catch (e) {}
      finish();
    };
    img.onerror = () => finish();
    img.src = src;
  });
}

