    + `<button type="button" class="eo-act" data-eo-rename="${gi}">改名</button>`
    + `<button type="button" class="eo-act eo-gdel" data-eo-gdel="${gi}">删组</button></div>`
    + (named ? `<p class="eo-hint">${escapeHTML(_eoGrpHint(_emoOwnOnly(), g.g))}</p>` : '')
