    const n = silentBatch(ids, muted);
    _silentCommit(n > 0);
    const label = kind === 'group' ? '个群' : '位联系人';
    if (!n) showToast(muted ? '这些' + label + '都已经关着了' : '这些' + label + '都已经开着了');
