function patchMessageBadges(m) {
  const el = _findMsgNode($('#messageList'), m);
  if (!el) return;
  const old = el.querySelector('.msg-badges');
  if (old) old.remove();
  const html = _msgBadgesHTML(m);
  if (!html) return;
   
   
  const wrapEl = el.querySelector('.bubble-wrap') || el;
  let foot = wrapEl.querySelector('.msg-foot');
  if (!foot) {
    const anchor = wrapEl.querySelector('.emo-line') || wrapEl.querySelector('.message-meta');
    if (!anchor) { wrapEl.insertAdjacentHTML('beforeend', '<div class="msg-foot">' + html + '</div>'); return; }
    anchor.insertAdjacentHTML('beforebegin', '<div class="msg-foot"></div>');
    foot = wrapEl.querySelector('.msg-foot');
    const emo = wrapEl.querySelector('.emo-line');
    if (emo && emo.parentElement !== foot) foot.appendChild(emo);
  }
  foot.insertAdjacentHTML('afterbegin', html + (foot.querySelector('.emo-line') ? '<i class="ft-sep">·</i>' : ''));
}

 
 
 
 
 
 
function patchMessage(m) {
  const el = _findMsgNode($('#messageList'), m);
  if (!el) return false;
  const [miniImg, miniPartner, miniMine] = getMiniAvatarHTML();
  let next;
  try { next = _buildMessageHTML(m, miniImg, miniMine, miniPartner); }
  catch (e) { return false; }    
  if (!next) return false;
  el.replaceWith(next);
  initLazyImages(next);    
  _stickWatch();           
  return true;
}

 
 
 
 
function patchMessageRemove(m, idx) {
  if (typeof idx === 'number' && idx >= 0) {
    if (idx < _msgEnd) _msgEnd = Math.max(0, _msgEnd - 1);
    if (idx < _msgStart) _msgStart = Math.max(0, _msgStart - 1);
    if (idx < _lastMsgCount) _lastMsgCount = Math.max(0, _lastMsgCount - 1);
  }
  const el = _findMsgNode($('#messageList'), m);
  if (!el) return false;
  const prev = el.previousElementSibling;
  const next = el.nextElementSibling;
  const orphanDay = !!prev && prev.classList.contains('day-label') && (!next || next.classList.contains('day-label'));
  const parent = el.parentNode;
  if (parent) parent.removeChild(el);
  if (orphanDay && prev.parentNode) prev.parentNode.removeChild(prev);
  _stickWatch();
  return true;
}



function _coStateText(v) {
  if (!v) return '这条邀请已经不在了';
  if (v.status === 'yes') {
     
     
     
    const withMe = (typeof _plWith === 'function') && _plWith() === v.cid;
    const same = !v.trackId || (typeof plCur !== 'function') || ((plCur() || {}).id === v.trackId);
     
    if (withMe && same && !v.trackId && typeof plCur === 'function' && !plCur()) return '一起听着 · 点卡去挑一首';
    return (withMe && same) ? '正在一起听' : '一起听了';
  }
  if (v.status === 'switch') return '切过去听了';
  if (v.status === 'later') return v.manual ? 'TA 说等一会儿 · 会回来' : '先放一放';
  if (v.status === 'no') return v.trackId ? 'TA 没答应这首' : 'TA 没答应';    
  return v.manual ? '等 TA 回话 · 点开' : '等你回话 · 点开';
}
function _coCardEl(m, miniPartner, miniMine) {
  const v = (typeof plInviteOf === 'function') ? plInviteOf(m.co) : null;
  const cid = (v && v.cid) || (typeof data !== 'undefined' && data.activeChat) || '';
  const c = ((typeof data !== 'undefined' && data.contacts) || []).find(x => x && x.id === cid) || null;
  const t = (v && typeof plById === 'function') ? plById(v.trackId) : null;
   
   
   
  const mine = !!(v && v.manual);
   
   
  const wrap = document.createElement('article');
  wrap.className = 'message message-co' + (mine ? ' mine' : '');
  wrap.dataset.id = m.id;
   
   
   
   
   
  const card = document.createElement('div');
   
   
   
  card.className = 'bubble cl-card';
  if (v) card.dataset.co = v.id;
  const avs = document.createElement('span');
  avs.className = 'cl-avs';
  const av = (src, name) => {
    const i = document.createElement('i');
    i.className = 'cl-av';
    if (src) { const img = document.createElement('img'); img.src = src; img.alt = ''; img.onerror = function () { this.remove(); }; i.appendChild(img); }
    else i.textContent = String(name || '我').trim().slice(0, 1) || '我';
    return i;
  };
  const meName = (typeof chatMyName === 'function' ? chatMyName(cid) : '') || '我';
  const meAv = (typeof chatMyAvatar === 'function' ? chatMyAvatar(cid) : '') || '';
   
   
   
   
   
  avs.appendChild(av(typeof chatAvatarOf === 'function' ? chatAvatarOf(c) : (c && c.avatar), chatNameOf(c) || 'TA'));
  avs.appendChild(av(meAv, meName));
  const tx = document.createElement('span');
  tx.className = 'cl-tx';
  const b = document.createElement('b');
   
  b.textContent = t ? '一起听《' + t.name + '》' : (v && !v.trackId ? '一起听 · 不限歌' : '一起听');
  const sm = document.createElement('small');
  sm.textContent = _coStateText(v);
  tx.appendChild(b); tx.appendChild(sm);
  card.appendChild(avs); card.appendChild(tx);
   
   
   
   
   
   
  const box = document.createElement('div');
  box.className = 'bubble-wrap';
  box.appendChild(card);
  const badges = (typeof _msgBadgesHTML === 'function') ? _msgBadgesHTML(m) : '';
  const emo = (typeof _emoLineHTML === 'function') ? _emoLineHTML(m) : '';
  if (badges || emo) {
    const foot = document.createElement('div');
    foot.className = 'msg-foot';
    foot.innerHTML = badges + (badges && emo ? '<i class="ft-sep">·</i>' : '') + emo;
    box.appendChild(foot);
  }
  if (m.time) {
    const meta = document.createElement('div');
    meta.className = 'message-meta';
    meta.innerHTML = '<span class="ft-time">' + escapeHTML(String(m.time)) + '</span>';
    box.appendChild(meta);
  }
  if (mine) {
    wrap.appendChild(box);
    if (miniMine) wrap.insertAdjacentHTML('beforeend', miniMine);
  } else {
    if (miniPartner) wrap.insertAdjacentHTML('afterbegin', miniPartner);
    wrap.appendChild(box);
  }
  return wrap;
}
 
 
 
 
 
function _lcClock(sec) {
  const s = Math.max(0, Math.round(Number(sec) || 0));
  return Math.floor(s / 60) + ':' + (s % 60 < 10 ? '0' : '') + (s % 60);
}
function _lcPlayingNow(l) {
  try {
    const cur = (typeof plCur === 'function') ? plCur() : null;
    return !!(cur && String(cur.id) === String(l && l.tid));
  } catch (e) { return false; }
}
function _lcChatCardHTML(m) {
  const l = m.lyr || {};
  const lines = Array.isArray(l.lines) ? l.lines : [];
  const melody = l.mode === 'melody';
  const seg = Array.isArray(l.seg) ? l.seg : null;
  const now = _lcPlayingNow(l);
  const state = now ? '正在听' : '听这一首 ›';
  let body = '';
  if (!melody && lines.length) {
    body = '<div class="lc-quote">' + lines.map(x =>
      '<div class="lc-line"><b>' + escapeHTML(screenSafeText(x.txt)) + '</b>'
      + (x.tr ? '<small>' + escapeHTML(screenSafeText(x.tr)) + '</small>' : '') + '</div>').join('') + '</div>';
  } else if (seg) {
     
    const dur = Number(l.dur) || 0;
    const a = Number(seg[0]) || 0, b = Number(seg[1]) || 0;
    const left = dur > 0 ? Math.max(0, Math.min(100, a / dur * 100)) : 0;
    const wide = dur > 0 ? Math.max(6, Math.min(100 - left, (b - a) / dur * 100)) : 26;
    body = '<div class="lc-seg">'
      + '<span class="lc-seg-track"><i style="left:' + left.toFixed(1) + '%;width:' + wide.toFixed(1) + '%"></i></span>'
      + '<span class="lc-seg-t">' + _lcClock(a) + ' – ' + _lcClock(b) + '</span></div>';
  }
  const src = l.name ? '《' + escapeHTML(String(l.name)) + '》' + (l.artist ? ' · ' + escapeHTML(String(l.artist)) : '') : '';
   
   
   
  return '<div class="bubble lc-card' + (melody ? ' lc-melody' : '') + '" data-lc-tid="' + escapeHTML(String(l.tid || '')) + '"'
    + (seg ? ' data-lc-seg="' + escapeHTML(String(Number(seg[0]) || 0)) + '"' : '') + '>'
    + '<div class="lc-hd"><span>' + (melody ? '这一段' : '摘一句') + '</span><span class="lc-at">' + state + '</span></div>'
    + body
    + (src ? '<div class="lc-src">' + src + '</div>' : '')
    + '</div>';
}
 
 
 
 
 
 
 
 
function _favChatCardHTML(m) {
  const f = (m && m.fav) || {};
  const words = String(f.text || '').trim();
  const imgs = Array.isArray(f.imgs) ? f.imgs.filter(Boolean).slice(0, 4) : [];
  const v = f.voice && (f.voice.src || (Number(f.voice.dur) || 0) > 0) ? f.voice : null;
  if (!words && !imgs.length && !v) return '';    
  const who = (typeof partnerName === 'function' && partnerName()) || 'TA';
  const d = new Date(f.ts || 0);
  const date = d.getFullYear() ? (d.getMonth() + 1) + '月' + d.getDate() + '日' : '';
   
   
  const kind = String(f.kind || 'msg');
  const kindTag = kind === 'feed' ? '朋友圈' : (kind === 'mail' ? (f.mailType === 'sent' ? '寄出的信' : '一封信') : '');
  let inner = '';
   
   
  if (v) {
    const dur = Math.round(Number(v.dur) || 0);
     
     
    inner += '<button type="button" class="favc-voice' + (v.src ? '' : ' cut') + '"'
      + ' data-fav-voice="' + escapeHTML(String(m.id || '')) + '"'
      + (v.src ? '' : ' data-cut="1"')
      + ' aria-label="播放这条语音"><span class="favc-tri" aria-hidden="true"></span>'
      + (dur ? '<span class="favc-dur">' + dur + '"</span>' : '') + '</button>';
  }
  if (imgs.length === 1) inner += '<img class="favc-img" alt="收藏的图片" data-src="' + escapeHTML(imgs[0]) + '" data-lazy-img="true">';
  else if (imgs.length > 1) inner += '<div class="favc-imgs">' + imgs.map(s => '<img alt="收藏的图片" data-src="' + escapeHTML(s) + '" data-lazy-img="true">').join('') + '</div>';
  if (words) inner += '<div class="favc-txt">' + kaomojiHTML(screenSafeText(words)) + '</div>';
  if (f.reason) inner += '<div class="favc-reason">当时收下 · ' + escapeHTML(screenSafeText(f.reason)) + '</div>';
  return '<div class="bubble favc-card"><div class="favc-hd"><span>' + escapeHTML(who) + ' 的收藏'
    + (kindTag ? '<b class="favc-kind">' + escapeHTML(kindTag) + '</b>' : '') + '</span>'
    + (date ? '<span class="favc-date">' + date + '</span>' : '') + '</div>' + inner + '</div>';
}

 
 
 
function _lcTextOf(m) {
  const l = (m && m.lyr) || null;
  if (!l) return '';
  const lines = Array.isArray(l.lines) ? l.lines : [];
  if (l.mode === 'melody' || !lines.length) {
    const seg = Array.isArray(l.seg) ? l.seg : null;
    return '这一段 · 《' + String(l.name || '') + '》' + (seg ? ' ' + _lcClock(seg[0]) + '–' + _lcClock(seg[1]) : '');
  }
  return lines.map(x => String(x.txt || '')).filter(Boolean).join(' ') + (l.name ? ' 《' + String(l.name) + '》' : '');
}
 
 
function _lcCopyText(m) {
  const l = (m && m.lyr) || null;
  if (!l || l.mode === 'melody') return '';
  const lines = Array.isArray(l.lines) ? l.lines : [];
  if (!lines.length) return '';
  const out = [];
  lines.forEach(x => {
    if (x.txt) out.push(String(x.txt));
    if (x.tr) out.push(String(x.tr));
  });
  out.push('—— 《' + String(l.name || '') + '》' + (l.artist ? ' ' + String(l.artist) : ''));
  return out.join('\n');
}

 
 
 
 
 
