        if (bh.tsEnabled && _images.length && _rand(bh.imageProb)) _attachSticker(again, _images, bh);
        else if (bh.tsEnabled && _stickers.length && _rand(bh.stickerProb)) _attachSticker(again, _stickers, bh);
        if (target.sender) again.sender = target.sender;    
        stream.push(again);
