msgList.addEventListener('click', e => {
   
   
   
  const emoRc = e.target.closest('[data-emo-recall]');
  if (emoRc) {
    const wrap = emoRc.closest('.bubble-wrap');
    const d = wrap && wrap.querySelector('.emo-recall-detail');
    if (d) { const show = d.hidden; d.hidden = !show; emoRc.setAttribute('aria-expanded', show ? 'true' : 'false'); }
    return;
  }
   
   
   
   
   
   
  const cardRc = e.target.closest('[data-card-recall]');
  if (cardRc) {
    const wrap = cardRc.closest('.bubble-wrap');
    const d = wrap && wrap.querySelector('.card-recall-detail[data-card-detail]');
    if (d) {
      const show = d.hidden;
      d.hidden = !show;
      if (show) d.style.removeProperty('display');
      else d.style.setProperty('display', 'none', 'important');
      cardRc.setAttribute('aria-expanded', show ? 'true' : 'false');
    }
    return;
  }
  const cardDetailTrig = e.target.closest('.card-recall-detail[data-card-detail]');
  if (cardDetailTrig && !e.target.closest('button')) {
    const wrap = cardDetailTrig.closest('.bubble-wrap');
    const btn = wrap && wrap.querySelector('[data-card-recall]');
    if (btn) btn.click();
    return;
  }
  let trigger = e.target.closest('.bubble.recalled[data-recalled]');
  if (!trigger) {
     
     
     
     
    const peek = e.target.closest('.recall-peek-inline[data-peek-body]');
    if (peek && !e.target.closest('button,a')) trigger = peek;
  }
  if (!trigger) return;
  const message = trigger.closest('.message');
  const body = message && message.querySelector('.recall-peek-inline[data-peek-body]');
  if (!body) return;
  const show = body.hidden;
  body.hidden = !show;
   
   
   
   
  if (show) body.style.removeProperty('display');
  else body.style.setProperty('display', 'none', 'important');
  const btn = message.querySelector('.recall-peek-toggle');
  if (btn) { btn.textContent = show ? '收起' : '查看'; btn.setAttribute('aria-expanded', show ? 'true' : 'false'); }
   
   
   
   
  if (show) { try { body.scrollIntoView({ block: 'nearest' }); } catch (err) {} }
  closeMsgActions();
});

 
