  const fullEl = $('#callFull');
  if (fullEl) { fullEl.hidden = true; fullEl.classList.remove('connected'); }
   
  try { if (data.appearance && data.appearance.bgKeepAlive) setBackgroundKeepAlive(true); } catch {}
   
