  const id = r.dataset.bindId;
  const also = !!(document.getElementById('cardsBindAlso') && document.getElementById('cardsBindAlso').checked);
  _closeCardsBind();
  data.groups[_bindGi].contactId = id;
   
  let extra = 0;
