const _COL_SET_FIELDS = [
  ['#collectTaMsg', 'taMsgProb'],
  ['#collectTaMail', 'taMailProb'],
  ['#collectTaSend', 'taSendProb']    
];
function _colSetDef(k) {
  const d = (typeof defaults === 'object' && defaults && defaults.collectSettings) || {};
  return Number.isFinite(d[k]) ? d[k] : 0;
}
function renderCollectSettings() {
  const cs = data.collectSettings || {};
  _COL_SET_FIELDS.forEach(f => { const el = $(f[0]); if (el) el.value = Number.isFinite(cs[f[1]]) ? cs[f[1]] : _colSetDef(f[1]); });
}
function saveCollectSettings() {
  if (!data.collectSettings) data.collectSettings = {};
  const cs = data.collectSettings;
   
   
  const before = {};
  _COL_SET_FIELDS.forEach(f => { before[f[1]] = cs[f[1]]; });
  _COL_SET_FIELDS.forEach(f => {
    const el = $(f[0]); if (!el) return;
     
     
     
     
     
    const txt = (typeof numInputText === 'function') ? numInputText(el.value) : String(el.value == null ? '' : el.value).trim();
    if (!txt) { el.value = ''; return; }
    const v = Number(txt);
    cs[f[1]] = Number.isFinite(v) ? Math.max(0, Math.min(100, Math.round(v))) : _colSetDef(f[1]);
    if (typeof window.setNumSafe === 'function') window.setNumSafe(el, cs[f[1]], _colSetDef(f[1]));
    else el.value = cs[f[1]];    
  });
  const changed = _COL_SET_FIELDS.some(f => String(before[f[1]]) !== String(cs[f[1]]));
  save();
  if (changed) autoSaveToast('收藏设置已保存');
}
function openCollectSettings() {
  const mask = $('#colSetMask');
  if (!mask) return;
  renderCollectSettings();
  mask.hidden = false;
}
function closeCollectSettings() {
  const mask = $('#colSetMask');
  if (mask) mask.hidden = true;
}
(function bindCollectSettings() {
  const btn = $('#colSetBtn'); if (btn) btn.onclick = openCollectSettings;
  const close = $('#colSetClose'); if (close) close.onclick = closeCollectSettings;
  const mask = $('#colSetMask');
  if (mask) mask.addEventListener('click', e => { if (e.target === mask) closeCollectSettings(); });    
  const sheet = $('#colSetSheet');
  if (sheet) { sheet.addEventListener('input', saveCollectSettings); sheet.addEventListener('change', saveCollectSettings); }
})();



const FAV_NOTE_MAX = 120;
let _favNoteAt = null;    

function openFavNote(ts, cid) {
  const at = _favLocate(ts, cid);
  if (!at) return;
  const f = at.list[at.i];
  if (!f || f.by === 'ta') return;    
  _favNoteAt = { ts: f.ts, cid: at.cid };
  const inp = $('#favNoteInput');
  if (inp) inp.value = f.reason || '';
  const mask = $('#favNoteMask');
  if (mask) mask.hidden = false;
  if (inp) inp.focus();
}
function closeFavNote() {
  const mask = $('#favNoteMask');
  if (mask) mask.hidden = true;
  _favNoteAt = null;
}
function saveFavNote() {
  if (!_favNoteAt) return;
  const at = _favLocate(_favNoteAt.ts, _favNoteAt.cid);
  if (!at) { closeFavNote(); return; }    
  const inp = $('#favNoteInput');
  const v = String(inp && inp.value || '').trim().slice(0, FAV_NOTE_MAX);
  if (inp) inp.value = v;                
  if (v) at.list[at.i].reason = v; else delete at.list[at.i].reason;    
  if (!_collectWriteKey(at.key, at.list)) { closeFavNote(); renderCollectList(); showToast(COLLECT_LOST_TEXT); return; }
  renderCollectList();
  closeFavNote();
}
(function bindFavNote() {
  const ok = $('#favNoteSave'); if (ok) ok.onclick = saveFavNote;
  const close = $('#favNoteClose'); if (close) close.onclick = closeFavNote;
  const mask = $('#favNoteMask');
  if (mask) mask.addEventListener('click', e => { if (e.target === mask) closeFavNote(); });    
})();
 
 
 
 
 
 

const SEARCH_MAX = { msg: 300, letter: 100, collect: 100, card: 60 };

 
 
const SEARCH_WHO_KEY = 'ordinal-search-who';
let currentSearchWho = (() => { try { return localStorage.getItem(SEARCH_WHO_KEY) || 'all'; } catch (e) { return 'all'; } })();
function saveSearchWho(w) {
  currentSearchWho = w || 'all';
  try {
    if (currentSearchWho === 'all') localStorage.removeItem(SEARCH_WHO_KEY);
    else localStorage.setItem(SEARCH_WHO_KEY, currentSearchWho);
  } catch (e) {}
}
 
 
 
function _searchWhoLabel(cid) {
  const c = (data.contacts || []).find(x => x && x.id === cid);
  if (!c) return '已不在通讯录';
  return (fixedNameOf(c) || '未命名') + (c.kind === 'group' ? ' · 群' : '');
}
 
 
 
function _searchWhoRender(list, who) {
  const el = $('#searchWho');
  if (!el) return;
  if (!list || list.length < 2) { el.hidden = true; el.innerHTML = ''; return; }
  el.hidden = false;
  el.innerHTML = [{ id: 'all', n: list.reduce((a, b) => a + b.n, 0), label: '全部' }].concat(list).map(b =>
    `<button type="button" class="fchip${who === b.id ? ' on' : ''}" data-search-who="${escapeHTML(b.id)}">${escapeHTML(b.label)}<span class="n">${b.n}</span></button>`).join('');
}

function _searchHlHTML(text, q) {
   
  const lq = q.toLowerCase();
  const src = screenSafeText(text);    
  let out = '';
  let rest = src;
  let idx = rest.toLowerCase().indexOf(lq);
  let guard = 0;
  while (idx > -1 && guard < 20) {
    if (idx > 0) out += escapeHTML(rest.slice(0, idx));
    out += '<mark class="hl">' + escapeHTML(rest.slice(idx, idx + q.length)) + '</mark>';
    rest = rest.slice(idx + q.length);
    idx = rest.toLowerCase().indexOf(lq);
    guard++;
  }
  return out + escapeHTML(rest);
}

function _searchGroupHTML(name, count) {
  return '<div class="search-group"><span class="search-group-name">' + name + '</span><span class="search-group-n">' + count + '</span></div>';
}
function _simpleRowHTML(kind, attrs, title, meta, snippetHtml) {
  return '<div class="search-row search-row-simple" role="button" tabindex="0" data-kind="' + kind + '" ' + attrs + '>'
    + '<span class="search-kind-ic search-kind-' + kind + '"></span>'
    + '<span class="search-main"><span class="search-top"><span class="search-who">' + title + '</span>'
    + '<span class="search-time">' + meta + '</span></span>'
    + '<span class="search-text">' + snippetHtml + '</span></span></div>';
}

let _searchTimer = null;
 
 
 
let _searchComposing = false;
const SEARCH_DEBOUNCE_MS = 160;

function doSearch() {
  const input = $('#searchInput');
  const status = $('#searchStatus');
  const body = $('#searchBody');
  const q = input.value.trim();
  const clearBtn = $('#searchClear');
  clearBtn.hidden = !q;
  if (!q) {
    status.textContent = '';
    _searchWhoRender([], 'all');
    body.innerHTML = '<div class="search-empty"><svg viewBox="0 0 24 24" width="34" height="34" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/></svg>' + (_searchMode === 'all' ? '搜索聊天、信件、收藏和字卡' : '搜索聊天记录') + '<br>输入关键词，点结果直达</div>';
    return;
  }
  const lq = q.toLowerCase();
  const html = [];
  const counts = [];

   
   
   
   
  const _searchAll = _searchMode === 'all'; const chatBuckets = [];
   
  const _pool = _searchCid ? ((data.chats && data.chats[_searchCid]) ? { [_searchCid]: data.chats[_searchCid] } : {}) : (data.chats || {});
  for (const cid of Object.keys(_pool)) {
    const rows = []; let n = 0;
    const ms = (data.chats[cid].msgs || []).slice().reverse();
    for (const m of ms) {
      if (!m || m.from === 'system' || m.recalled) continue;
       
       
       
       
      const t = (typeof msgLiveText === 'function' ? msgLiveText(m) : m.text) || (typeof _lcTextOf === 'function' ? _lcTextOf(m) : '');
      if (!t || t === '[表情包]' || !t.toLowerCase().includes(lq)) continue;
      n++;
      if (rows.length >= SEARCH_MAX.msg) continue;
      const mine = m.from === 'me';
       
       
       
       
       
      const mem = (!mine && m.sender && typeof memberContactOf === 'function') ? memberContactOf(m.sender) : null;
      const who = mine ? chatMyName(cid)
        : (mem ? memberDisplayName(m.sender, cid) : chatPartnerNameOf(cid));
      const avSrc = mine ? chatMyAvatar(cid)
        : (mem ? chatAvatarOf(mem) : ((typeof chatPartnerAvatarOf === 'function') ? chatPartnerAvatarOf(cid) : chatPartnerAvatar()));
      const av = avatarHTML(avSrc, firstChar(who));
      const dateLabel = m.date ? '<small>' + escapeHTML(formatDateLabel(m.date)) + '</small>' : '';
       
       
       
      const fitCid = (mem && mem.id) ? mem.id : cid;
      const shownT = (!mine && typeof taFit === 'function') ? taFit(t, fitCid) : t;
      rows.push('<div class="search-row" role="button" tabindex="0" data-kind="msg" data-cid="' + escapeHTML(cid) + '" data-id="' + escapeHTML(m.id) + '">'
        + '<span class="mini-avatar">' + av + '</span>'
        + '<span class="search-main"><span class="search-top"><span class="search-who">' + escapeHTML(who) + dateLabel + '</span>'
        + '<span class="search-time">' + escapeHTML(m.time || '') + '</span></span>'
        + '<span class="search-text">' + _searchHlHTML(shownT, q) + '</span></span></div>');
    }
    chatBuckets.push({ id: cid, n, rows, label: _searchWhoLabel(cid) });
  }
   
  const whoOrder = (data.contacts || []).map(c => c.id);
  const whoRank = id => { const i = whoOrder.indexOf(id); return i < 0 ? 9e9 : i; };
  chatBuckets.sort((a, b) => whoRank(a.id) - whoRank(b.id));
   
  const who = chatBuckets.some(b => b.id === currentSearchWho) ? currentSearchWho : 'all';
  _searchWhoRender(chatBuckets, who);
   
   
   
  const hitBuckets = chatBuckets.filter(b => b.n > 0);
  const perBucket = Math.ceil(SEARCH_MAX.msg / Math.max(1, hitBuckets.length));
  const kept = who === 'all' ? hitBuckets : chatBuckets.filter(b => b.id === who);
  const msgRows = kept.reduce((a, b) => a.concat(who === 'all' ? b.rows.slice(0, perBucket) : b.rows), []);
  const msgN = kept.reduce((a, b) => a + b.n, 0);
   
   
  if (msgN) { counts.push('聊天 ' + msgN); if (_searchAll) html.push(_searchGroupHTML('聊天', msgN)); html.push(msgRows.join('')); }

   
  const letterRows = []; let letterN = 0;
  const addLetter = (arr, m, isSent, label) => {
    letterN++;
    if (letterRows.length >= SEARCH_MAX.letter) return;
     
    const shownL = (!isSent && typeof taFit === 'function') ? taFit(m.text || '', m.cid || mainChatId()) : (m.text || '');
    letterRows.push(_simpleRowHTML('letter', 'data-idx="' + arr.indexOf(m) + '" data-sent="' + (isSent ? 1 : 0) + '"',
      escapeHTML(label), escapeHTML(m.postmark || ''), _searchHlHTML(shownL, q)));
  };
  const recv = _searchAll ? (data.receivedLetters || []).slice().reverse() : [];
  for (const m of recv) if (m && m.text && m.text.toLowerCase().includes(lq)) addLetter(data.receivedLetters || [], m, false, _mbOwnerName(m.cid || mainChatId()) + ' 的来信');
  const sent = _searchAll ? (data.sentLetters || []).slice().reverse() : [];
  for (const m of sent) if (m && m.text && m.text.toLowerCase().includes(lq)) addLetter(data.sentLetters || [], m, true, '寄给 ' + _mbOwnerName(m.cid || mainChatId()));
  if (letterN) { counts.push('信件 ' + letterN); html.push(_searchGroupHTML('信件', letterN)); html.push(letterRows.join('')); }

   
   
   
  const collectRows = []; let collectN = 0;
  try {
    for (const b of (_searchAll ? collectBooks() : [])) {
      const cid = b.cid;
      const list = collectBookAt(b.key);
      for (const f of list.slice().reverse()) {
        if (!f || !f.text || !f.text.toLowerCase().includes(lq)) continue;
        collectN++;
        if (collectRows.length >= SEARCH_MAX.collect) continue;
        const kindLabel = f.kind === 'mail' ? '信件' : '聊天';
         
        const shownC = (typeof collectFitText === 'function') ? collectFitText(f, cid) : (f.text || '');
        collectRows.push(_simpleRowHTML('collect', 'data-cid="' + escapeHTML(cid) + '" data-cts="' + escapeHTML(f.ts || '') + '"',
          escapeHTML(((f.by || 'me') === 'ta' ? partnerName() + ' 的收藏' : '我的收藏') + ' · ' + kindLabel),
          '', _searchHlHTML(shownC, q)));
      }
    }
  } catch (e) {}
  if (collectN) { counts.push('收藏 ' + collectN); html.push(_searchGroupHTML('收藏', collectN)); html.push(collectRows.join('')); }

   
   

   
  const cardRows = []; let cardN = 0;
  for (const g of (_searchAll ? (data.groups || []) : [])) {
    const cat = g.category || '主字卡';
    const gi = (data.groups || []).indexOf(g);    
    for (const c of (g.cards || [])) {
      const text = cardText(c) || '';    
      if (!text || !text.toLowerCase().includes(lq)) continue;
      cardN++;
      if (cardRows.length >= SEARCH_MAX.card) break;
       
       
       
       
       
      cardRows.push(_simpleRowHTML('card', 'data-cat="' + escapeHTML(cat) + '" data-q="' + escapeHTML(q) + '"'
        + ' data-grp="' + escapeHTML(g.name || '') + '" data-scope="' + escapeHTML(cardScope(g)) + '" data-preset="' + (g.preset ? 1 : 0) + '"'
        + ' data-gi="' + gi + '"',
        escapeHTML(g.name || '未分组') + (g.preset ? '<small>内置</small>' : ''), escapeHTML(cat), _searchHlHTML(text, q)));
    }
  }
  if (cardN) { counts.push('字卡 ' + cardN); html.push(_searchGroupHTML('字卡', cardN)); html.push(cardRows.join('')); }

  const shown = msgRows.length + letterRows.length + collectRows.length + cardRows.length;
  const total = msgN + letterN + collectN + cardN;
   
  const whoTip = who === 'all' ? '' : '<span class="search-filter-who">只看 ' + escapeHTML(_searchWhoLabel(who)) + '</span> · ';
  if (!total) {
    status.textContent = '';
     
    body.innerHTML = '<div class="search-empty">没有找到与「<span class="hl">' + escapeHTML(q) + '</span>」相关的内容<br>' + (who !== 'all' && chatBuckets.length >= 2 ? '「' + escapeHTML(_searchWhoLabel(who)) + '」的聊天里没有这一句 · 点上面「全部」看所有会话' : (_searchCid ? '这个会话的聊天记录里没有这一句 · 换个关键词试试' : (_searchMode === 'all' ? '换个关键词试试' : '这里只搜聊天记录 · 换个关键词试试'))) + '</div>';
    return;
  }
  status.innerHTML = whoTip + '共找到 <b>' + total + '</b> 条 · ' + counts.join(' · ') + (total > shown ? '（部分已省略，请细化）' : '');
  body.innerHTML = html.join('');
}

 
 
 
 
 
let _searchMode = 'all';
let _searchCid = '';           
function openSearch(mode, cid) {
  _searchMode = (mode === 'chat') ? 'chat' : 'all';
  _searchCid = (mode === 'chat' && cid) ? String(cid) : '';
  const _si = $('#searchInput');
  const ph = _searchCid ? '在这个会话的聊天记录里搜' : (_searchMode === 'all' ? '搜索聊天 / 信件' : '搜索聊天记录');
  if (_si) { _si.placeholder = ph; _si.setAttribute('aria-label', _searchCid ? '搜索这个会话的聊天记录' : (_searchMode === 'all' ? '搜索全部内容' : '搜索聊天记录')); }
  $('#searchMask').hidden = false;
  const inp = $('#searchInput');
  inp.value = '';
  doSearch();
  setTimeout(() => { try { inp.focus(); } catch {} }, 60);
}

function closeSearch() {
  const mask = $('#searchMask');
  if (!mask.hidden) {
    mask.hidden = true;
    if (_searchTimer) { clearTimeout(_searchTimer); _searchTimer = null; }
  }
}

 
function _searchFlash(el) {
  if (!el) return;
  el.classList.add('search-hit');
  setTimeout(() => el.classList.remove('search-hit'), 1600);
}
 
 
function _searchOpenLetter(isSent, idx) {
  const arr = isSent ? (data.sentLetters || []) : (data.receivedLetters || []);
  const m = arr[idx];
  if (!m) return;
  _mbScopeSet(m.cid || 'all');
  showView('mailbox');
  setTimeout(() => {
     
    const tab = document.querySelector(`.mailbox-tab[data-tab="${isSent ? 'sent' : (m.kind === 'reply' ? 'reply' : 'proactive')}"]`);
    if (tab) tab.click();
    if (isSent) { _openSentLetter(m); return; }
    if (m.read) { openLetterView(m); return; }
    const row = document.querySelector(`#${m.kind === 'reply' ? 'replyList' : 'proactiveList'} .mailbox-row[data-idx="${idx}"]`);
    if (!row) { _openReceivedLetter(m); return; }
    row.dataset.animated = 'true';
    row.classList.add('tearing');
    setTimeout(() => {
      _openReceivedLetter(m);
      row.dataset.animated = 'false';
    }, 450);
  }, 420);
}
 
function _searchOpenCollect(cid, cts) {
  showView('collect');
  setTimeout(() => {
    if (cid && cid !== data.activeChat && typeof switchChat === 'function') switchChat(cid);
    setTimeout(() => {
      const card = document.querySelector('#collectList .fav-card[data-cts="' + cts + '"]');
      if (card) { card.scrollIntoView({ block: 'center' }); _searchFlash(card); }
    }, 260);
  }, 340);
}
 
function _searchOpenCard(cat, q, grp, preset, scope, gi) {
  const _gi = Number(gi);
  if (preset) {
     
     
     
    const g = (data.groups || []).find(x => x && x.preset && x.name === grp);
    cardsSelectGroup(isFinite(_gi) ? _gi : -1, grp); groupSearch = '';
    currentSysCardsTab = (g && typeof presetFeatureOf === 'function') ? presetFeatureOf(g) : currentSysCardsTab;
    showView('syscards');
    setTimeout(() => { if (typeof renderSysCards === 'function') renderSysCards(); }, 60);
    return;
  }
  showView('cards');
   
   
  if (scope === 'own' || scope === 'public') { currentCardsScope = scope; if (typeof saveCardsScope === 'function') saveCardsScope(); }
  if (typeof saveCardsWho === 'function') saveCardsWho('all');
  cardsSelectGroup(-1, '');
  setTimeout(() => {
    try {
      const tab = document.querySelector('.cards-tab[data-cards-tab="' + cat + '"]');
      if (tab) tab.click();
    } catch (e) {}
    const row = document.getElementById('cardsSearchRow');
    if (row) row.hidden = false;
    const inp = document.getElementById('groupSearchInput');
    if (inp) { inp.value = q; if (typeof renderGroups === 'function') renderGroups(); }
  }, 380);
}

const _searchTopBtn = $('#searchTopBtn');
if (_searchTopBtn) _searchTopBtn.addEventListener('click', () => openSearch('chat'));
$('#searchBack').addEventListener('click', closeSearch);
$('#searchMask').addEventListener('click', e => { if (e.target === e.currentTarget) closeSearch(); });
$('#searchClear').addEventListener('click', () => {
  const inp = $('#searchInput');
  inp.value = '';
  doSearch();
  inp.focus();
});
$('#searchInput').addEventListener('compositionstart', () => { _searchComposing = true; });
$('#searchInput').addEventListener('compositionend', () => {
  _searchComposing = false;
  if (_searchTimer) clearTimeout(_searchTimer);
  _searchTimer = setTimeout(doSearch, SEARCH_DEBOUNCE_MS);
});
$('#searchInput').addEventListener('input', e => {
  if (_searchComposing || (e && e.isComposing)) return;    
  if (_searchTimer) clearTimeout(_searchTimer);
  _searchTimer = setTimeout(doSearch, SEARCH_DEBOUNCE_MS);
});
$('#searchInput').addEventListener('keydown', e => {
  if (e.key === 'Escape') closeSearch();
});
 
 
const _searchWhoEl = $('#searchWho');
if (_searchWhoEl) _searchWhoEl.addEventListener('click', e => {
  const chip = e.target.closest('.fchip');
  if (!chip || !_searchWhoEl.contains(chip)) return;
  saveSearchWho(chip.dataset.searchWho);
  doSearch();
});
$('#searchBody').addEventListener('click', e => {
  const row = e.target.closest('.search-row');
  if (!row) return;
  const kind = row.dataset.kind;
  if (kind === 'msg') {
    closeSearch();
    const cid = row.dataset.cid;
     
     
     
     
     
     
     
    if (cid && typeof switchChat === 'function') switchChat(cid);
    else if (typeof showView === 'function') showView('chat');
    if (typeof jumpToMessage === 'function') setTimeout(() => jumpToMessage(row.dataset.id), 80);
    return;
  }
  if (kind === 'letter') { closeSearch(); _searchOpenLetter(row.dataset.sent === '1', Number(row.dataset.idx)); return; }
  if (kind === 'collect') { closeSearch(); _searchOpenCollect(row.dataset.cid, row.dataset.cts); return; }
  if (kind === 'card') { closeSearch(); _searchOpenCard(row.dataset.cat, row.dataset.q, row.dataset.grp, row.dataset.preset === '1', row.dataset.scope, row.dataset.gi); return; }
});
 

 
function formatPostmarkDate() {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  return `${y}.${m}.${d}`;
}

let currentDraft = '';
let _isSending = false;



const _MB_SCOPE_KEY = 'ordinal-mailbox-scope';
let _mbScope = (() => { try { return localStorage.getItem(_MB_SCOPE_KEY) || 'all'; } catch (e) { return 'all'; } })();
function _mbScopeSet(cid) {
  _mbScope = cid || 'all';
  try {
    if (_mbScope === 'all') localStorage.removeItem(_MB_SCOPE_KEY);
    else localStorage.setItem(_MB_SCOPE_KEY, _mbScope);
  } catch (e) {}
}
 
function _mbScopeNow() {
  if (_mbScope === 'all') return 'all';
  return (data.contacts || []).some(c => c && c.id === _mbScope) ? _mbScope : 'all';
}
function _mbSingles() { return (data.contacts || []).filter(c => c && c.kind !== 'group'); }    
function _mbOwner(cid) { return (data.contacts || []).find(x => x && x.id === cid) || null; }
function _mbOwnerName(cid) { const c = _mbOwner(cid); return c ? (fixedNameOf(c) || 'TA') : '已不在通讯录'; }
 
 
 
 
function _mbLetters(which) {
  const scope = _mbScopeNow();
  const inBook = m => scope === 'all' || m.cid === scope;
  const all = which === 'sent'
    ? (data.sentLetters || []).map((m, idx) => ({ m, idx, sent: true }))
    : (data.receivedLetters || []).map((m, idx) => ({ m, idx, sent: false }));
  const keep = which === 'reply' ? r => r.m && r.m.kind === 'reply'
    : which === 'proactive' ? r => r.m && (r.m.kind || 'proactive') !== 'reply'
    : () => true;
  return all.filter(r => r.m && keep(r) && inBook(r.m));
}


function _mbLetterNo(m, which) {
  const arr = (which === 'sent' ? data.sentLetters : data.receivedLetters) || [];
  const who = m.cid || mainChatId();
  const mine = arr.map((x, idx) => (x && (x.cid || mainChatId()) === who ? { m: x, idx } : null)).filter(Boolean);
  const at = _mbOrdered(mine).findIndex(r => r.m === m);
  return at >= 0 ? mine.length - at : 1;
}
 
function _mbWriteTarget() {
  const s = _mbScopeNow();
  if (s !== 'all') return s;
  const a = data.activeChat;
  const c = (data.contacts || []).find(x => x && x.id === a && x.kind !== 'group');
  return c ? a : (_mbSingles()[0] || {}).id || 'c0';
}

 
 
 
function _letterRailFill(el, postmark, time, seq) {
  if (!el) return;
  const p = typeof _mbParsePostmark === 'function' ? _mbParsePostmark(postmark) : null;
  const wd = typeof _mbWeekday === 'function' ? _mbWeekday(p) : '';
  el.innerHTML = `<b>${p ? String(p.d).padStart(2, '0') : '--'}</b>`
    + `<i>${wd ? wd + ' ' : ''}${escapeHTML(time || '')}</i>`
    + (p ? '<u class="mo">' + p.m + '月</u>' : '')
     
    + (seq > 0 ? `<u class="sq">第 ${seq} 封</u>` : '');
}

 
 
 
