function _mbLetterWhy(m) {
  if (m && (m.rwhy === 'sys' || m.rwhy === 'shy')) return m.rwhy;
  return m && m.rsys ? 'sys' : '';
}
 
 
 
function _mbRollWhy() {
  const r = Math.random() * 100;
  return r < 10 ? 'sys' : r < 25 ? 'shy' : '';
}
 
 
 
 
 
 
function _showLetterReason(m, sent) {
  const rv = $('#letterViewReason');
  if (rv) {
     
    if (sent) {
      rv.hidden = false;
      rv.classList.add('sys');
      rv.innerHTML = escapeHTML('（你寄出去的信 · 不需要由头）');
    } else if (m && m.kind === 'reply' && m.replyTo) {
      rv.hidden = false;
      rv.classList.remove('sys');
      rv.innerHTML = '<span>回信</span><span class="letter-reply-link" data-jump-reply>回你 ' + escapeHTML(m.replyTo) + ' 的那封信</span>';
    } else if (m && _mbLetterWhy(m) === 'shy') {
      rv.hidden = false;
      rv.classList.remove('sys');
      rv.innerHTML = escapeHTML('（这句 TA 没好意思说 · 信是一笔一笔写的）');
    } else if (m && (m.reason || _mbLetterWhy(m) === 'sys')) {
      rv.hidden = false;
      const sys = !m.reason;
      rv.classList.toggle('sys', sys);
      rv.innerHTML = sys
        ? escapeHTML('（由头不是 TA 挑的 · 系统替 TA 塞了一句）')
        : '<span>由头</span>' + escapeHTML(m.reason);
    } else rv.hidden = true;
  }
  const iv = $('#letterViewImgs');
  if (iv) {
    const srcs = _letterImgsOf(m);
    if (!srcs.length) { iv.hidden = true; iv.className = 'letter-view-imgs'; iv.innerHTML = ''; }
    else {
      iv.hidden = false;
      if (srcs.length === 1) {
         
        iv.className = 'letter-view-imgs';
        iv.innerHTML = '<img class="letter-view-img" alt="信里的图" src="' + escapeHTML(srcs[0]) + '">';
      } else {
         
        iv.className = 'letter-view-imgs grid';
        iv.innerHTML = srcs.map(u => '<img alt="信里的图" src="' + escapeHTML(u) + '">').join('');
      }
       
       
      iv.querySelectorAll('img').forEach(im => {
        const drop = () => { im.remove(); if (!iv.querySelector('img')) iv.hidden = true; };
        im.onload = () => { if (im.naturalWidth < 48 || im.naturalHeight < 48) drop(); };
        im.onerror = drop;
      });
    }
  }
}
