const TB_INK_KEY = 'ordinal-tabbar-ink';
const HB_INK_KEY = 'ordinal-headbar-ink';
 
const BAR_INK_PRESETS = ['#2f3136', '#6f737b', '#f2f2f2', '#b9a68f', '#8fa8bf', '#93a69a', '#c2a3a3'];
function _barInkNorm(v) {
  return (typeof v === 'string' && /^#[0-9a-fA-F]{6}$/.test(v)) ? v.toLowerCase() : '';
}
function _barInkGet(kind) {
  try { return _barInkNorm(localStorage.getItem(kind === 'head' ? HB_INK_KEY : TB_INK_KEY) || ''); } catch (e) { return ''; }
}
 
function _barInkApply() {
  const one = (attr, vvar, c) => {
    if (c) { document.body.dataset[attr] = 'on'; document.body.style.setProperty(vvar, c); }
    else { delete document.body.dataset[attr]; document.body.style.removeProperty(vvar); }
  };
  one('tbInk', '--tb-ink', _barInkGet('tabbar'));
  one('hbInk', '--hb-ink', _barInkGet('head'));
}
 
function _barInkSet(kind, v) {
  const c = _barInkNorm(v), key = kind === 'head' ? HB_INK_KEY : TB_INK_KEY;
  if (c !== _barInkGet(kind)) {
    try { if (c) localStorage.setItem(key, c); else localStorage.removeItem(key); } catch (e) {}
    _barInkApply();
  }
  _barInkPaint();
}
 
function _barInkPaint() {
  $$('[data-ink-for]').forEach(box => {
    const c = _barInkGet(box.dataset.inkFor);
    box.querySelectorAll('.ink-sw').forEach(sw => {
      const on = (sw.dataset.ink || '') === c;
      sw.classList.toggle('on', on);
      sw.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    const pick = box.querySelector('.ink-pick');
    if (pick) pick.classList.toggle('on', !!c && BAR_INK_PRESETS.indexOf(c) < 0);
  });
}
$('#layoutMask') && $('#layoutMask').addEventListener('click', e => {
  const sw = e.target.closest('.ink-sw');
  if (!sw) return;
  const box = sw.closest('[data-ink-for]');
  if (box) _barInkSet(box.dataset.inkFor, sw.dataset.ink || '');
});
$('#layoutMask') && $('#layoutMask').addEventListener('input', e => {
  const pick = e.target.closest('.ink-pick');
  if (!pick) return;
  const box = pick.closest('[data-ink-for]');
  if (box) _barInkSet(box.dataset.inkFor, pick.value);
});
_barInkApply();      
_barInkPaint();

 
 
 
 
 
 
 
 
 
 
 
 
 
const HEADBAR_KEY = 'ordinal-headbar';
 
 
 
 
 
 
const HEADBAR_LEFT_KEY = 'ordinal-headbar-left';
 
 
 
 
 
 
const HEADBAR_MAX = 10;
 
 
 
 
 
const HEADBAR_DEFAULT = ['call', 'ap'];
const HEADBAR_LEFT_DEFAULT = [];
 
 
const HB_QUICK = { xinxun: 1, divine: 1 };
 
 
 
 
const HB_NAMEPOS_KEY = 'ordinal-headname-pos';
function hbNamePos() {
  let v = '';
  try { v = localStorage.getItem(HB_NAMEPOS_KEY) || ''; } catch (e) {}
  return v === 'left' ? 'left' : 'center';
}
 
function hbNamePosSet(v) {
  const next = v === 'left' ? 'left' : 'center';
  if (next === hbNamePos()) return false;
  try { localStorage.setItem(HB_NAMEPOS_KEY, next); } catch (e) {}
  renderHeadbar();
  renderHeadBarPanel();
  _layoutChanged();
  return true;
}

let _hbBuiltin = null;
let _hbPool = {};

function _hbBuiltins() {
  if (_hbBuiltin) return _hbBuiltin;
  _hbBuiltin = [];
  [['call', 'callBtn', '打电话'], ['ap', 'chatApBtn', '会话外观']].forEach(pair => {
    const el = document.getElementById(pair[1]);
    if (!el) return;
    el.dataset.hbKey = pair[0];     
    _hbBuiltin.push({ key: pair[0], name: pair[2], svg: (el.querySelector('svg') || {}).outerHTML || '' });
  });
  return _hbBuiltin;
}

 
 
function _hbCandidates() {
  const out = [], seen = {};
  _hbBuiltins().forEach(b => { seen[b.key] = 1; out.push({ key: b.key, name: b.name, svg: b.svg }); });
  _tbCandidates().forEach(c => {
    if (c.view === 'chats' || seen[c.view]) return;
    seen[c.view] = 1;
    out.push({ key: c.view, name: c.name, svg: c.svg });
  });
  return out;
}

 
 
function _hbList() {
   
  let raw = null;
  try { const s = localStorage.getItem(HEADBAR_KEY); if (s) raw = JSON.parse(s); } catch (e) {}
  const known = {};
  _hbCandidates().forEach(c => { known[c.key] = 1; });
  const out = [];
  (Array.isArray(raw) ? raw : HEADBAR_DEFAULT).forEach(k => {
    if (typeof k === 'string' && known[k] && out.indexOf(k) < 0) out.push(k);
  });
  return out.slice(0, HEADBAR_MAX);
}
function _hbWrite(list) { try { localStorage.setItem(HEADBAR_KEY, JSON.stringify(list)); } catch (e) {} }
 
 
 
 
const HEADBAR_UNSEED_KEY = 'ordinal-headbar-unseed-quick';
function _hbUnseedQuick() {
  try {
    if (localStorage.getItem(HEADBAR_UNSEED_KEY)) return;
    localStorage.setItem(HEADBAR_UNSEED_KEY, '1');
    const strip = s => {
      if (!s) return;
      let l = null;
      try { l = JSON.parse(s); } catch (e) { return; }
      if (!Array.isArray(l)) return;
      const out = l.filter(k => k !== 'xinxun' && k !== 'divine');
      if (out.length !== l.length) return out;
    };
    const list = strip(localStorage.getItem(HEADBAR_KEY));
    if (list) localStorage.setItem(HEADBAR_KEY, JSON.stringify(list));
    const left = strip(localStorage.getItem(HEADBAR_LEFT_KEY));
    if (left) localStorage.setItem(HEADBAR_LEFT_KEY, JSON.stringify(left));
  } catch (e) {}
}
 
 
function _hbLeftList() {
  let raw = null;
  try { const s = localStorage.getItem(HEADBAR_LEFT_KEY); if (s) raw = JSON.parse(s); } catch (e) {}
  const list = _hbList();
  const out = [];
  (Array.isArray(raw) ? raw : HEADBAR_LEFT_DEFAULT).forEach(k => {
    if (typeof k === 'string' && list.indexOf(k) >= 0 && out.indexOf(k) < 0) out.push(k);
  });
  return out;
}
function _hbLeftSet() {
  const set = {};
  _hbLeftList().forEach(k => { set[k] = 1; });
  return set;
}
function _hbWriteLeft(list) { try { localStorage.setItem(HEADBAR_LEFT_KEY, JSON.stringify(list)); } catch (e) {} }

 
 
 
 
 
function uiLayoutExport() {
  const out = {};
  const arr = k => {
    try {
      const s = localStorage.getItem(k);
      if (s === null) return null;
      const v = JSON.parse(s);
      return Array.isArray(v) ? v : null;
    } catch (e) { return null; }
  };
  const tb = arr(TABBAR_KEY); if (tb) out.tabbar = tb;
  const hb = arr(HEADBAR_KEY); if (hb) out.headbar = hb;
  const lf = arr(HEADBAR_LEFT_KEY); if (lf) out.headbarLeft = lf;
  try { if (localStorage.getItem(HB_NAMEPOS_KEY) === 'left') out.namePos = 'left'; } catch (e) {}
   
  const ti = _barInkGet('tabbar'), hi = _barInkGet('head');
  if (ti || hi) { out.ink = {}; if (ti) out.ink.tabbar = ti; if (hi) out.ink.headbar = hi; }
  return out;
}
 
 
 
function _uiCleanTabbar(list) {
  const known = {};
  _tbCandidates().forEach(c => { known[c.view] = 1; });
  const out = [];
  (Array.isArray(list) ? list : []).forEach(v => {
    if (typeof v === 'string' && known[v] && out.indexOf(v) < 0) out.push(v);
  });
  const arranged = out.filter(v => v !== TABBAR_ANCHOR).slice(0, TABBAR_MAX - 1);
  arranged.push(TABBAR_ANCHOR);
  return arranged;
}
function _uiCleanHeadbar(list) {
  const known = {};
  _hbCandidates().forEach(c => { known[c.key] = 1; });
  const out = [];
  (Array.isArray(list) ? list : []).forEach(k => {
    if (typeof k === 'string' && known[k] && out.indexOf(k) < 0) out.push(k);
  });
  return out.slice(0, HEADBAR_MAX);
}
function uiLayoutImport(bak, mode) {
  const res = { applied: 0, kept: 0 };
  if (!bak || typeof bak !== 'object') return res;
  const same = (a, b) => { try { return JSON.stringify(a) === JSON.stringify(b); } catch (e) { return false; } };
  const curList = k => { try { const s = localStorage.getItem(k); return s ? JSON.parse(s) : null; } catch (e) { return null; } };
  const over = mode !== 'merge';
   
  if (Array.isArray(bak.tabbar) && bak.tabbar.length) {
    const cur = curList(TABBAR_KEY);
    if (over || cur === null || same(cur, TABBAR_DEFAULT)) {
      try { _tbWrite(_uiCleanTabbar(bak.tabbar)); res.applied++; } catch (e) {}
    } else res.kept++;
  }
   
  let hb = null;
  if (Array.isArray(bak.headbar)) {
    const cur = curList(HEADBAR_KEY);
    if (over || cur === null || same(cur, HEADBAR_DEFAULT)) {
      hb = _uiCleanHeadbar(bak.headbar);
      try { _hbWrite(hb); res.applied++; } catch (e) {}
    } else { res.kept++; hb = _hbList(); }
     
     
    try { localStorage.setItem(HEADBAR_UNSEED_KEY, '1'); } catch (e) {}
  }
   
  if (Array.isArray(bak.headbarLeft)) {
    const cur = curList(HEADBAR_LEFT_KEY);
    if (over || cur === null || same(cur, HEADBAR_LEFT_DEFAULT)) {
      const list = hb || _hbList();
      const left = [];
      bak.headbarLeft.forEach(k => {
        if (typeof k === 'string' && list.indexOf(k) >= 0 && left.indexOf(k) < 0) left.push(k);
      });
      try { _hbWriteLeft(left); res.applied++; } catch (e) {}
    } else res.kept++;
  }
   
  if (bak.namePos === 'left' || bak.namePos === 'center') {
    let cur = '';
    try { cur = localStorage.getItem(HB_NAMEPOS_KEY) || ''; } catch (e) {}
    if (over || cur === '' || cur === 'center') {
      try {
        if (bak.namePos === 'left') localStorage.setItem(HB_NAMEPOS_KEY, 'left');
        else localStorage.removeItem(HB_NAMEPOS_KEY);
        res.applied++;
      } catch (e) {}
    } else res.kept++;
  }
   
  if (bak.ink && typeof bak.ink === 'object') {
    const inkOne = (k, key) => {
      const v = _barInkNorm(bak.ink[k]);
      let cur = ''; try { cur = _barInkNorm(localStorage.getItem(key) || ''); } catch (e) {}
      if (over || cur === '') {
        try { if (v) localStorage.setItem(key, v); else localStorage.removeItem(key); res.applied++; } catch (e) {}
      } else if (v && v !== cur) res.kept++;
    };
    inkOne('tabbar', TB_INK_KEY);
    inkOne('headbar', HB_INK_KEY);
    _barInkApply();
  }
   
  try { if (typeof renderTabbar === 'function') renderTabbar(); } catch (e) {}
  try { if (typeof renderHeadbar === 'function') renderHeadbar(); } catch (e) {}
  return res;
}

 
 
 
function _hbLayoutWrite(left, right) {
  _hbWrite(left.concat(right));
  _hbWriteLeft(left);
}
 
 
 
function _hbSetSide(k, side) {
  const list = _hbList();
  if (list.indexOf(k) < 0) return false;
  const left = _hbLeftList().filter(x => x !== k);
  const right = list.filter(x => x !== k && left.indexOf(x) < 0);
  if (side === 'left') left.push(k); else right.push(k);
  _hbLayoutWrite(left, right);
  renderHeadbar();
  renderHeadBarPanel();
  _layoutChanged();
  return true;
}
 
 
function _hbMoveSide(k, dir) {
  const list = _hbList(), leftSet = _hbLeftSet();
  if (list.indexOf(k) < 0) return false;
  const isLeft = !!leftSet[k];
  const side = list.filter(x => !!leftSet[x] === isLeft);
  const i = side.indexOf(k), j = i + dir;
  if (j < 0 || j >= side.length) return false;
  side[i] = side[j]; side[j] = k;       
  const other = list.filter(x => !!leftSet[x] !== isLeft);
  _hbLayoutWrite(isLeft ? side : other, isLeft ? other : side);
  renderHeadbar();
  renderHeadBarPanel();
  _layoutChanged();
  return true;
}

 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
let _barDrag = null;           
let _barSkipClickAt = 0;       

 
function _barPrevTip() {
  return ' 上面那条栏按住左右拖可以换位置，点一下就收起或放回。';
}

 
function _renderBarPreview(box) {
  if (!box) return;
  const list = _tbList();
  box.dataset.barKind = 'tabbar';
  box.dataset.barSide = '';
  box.dataset.barMode = 'toggle';
  _barBind(box);
  if (!list.length) {
    box.innerHTML = '<span class="tb-prev-empty">空的（这一排一枚都没放）</span>';
    return;
  }
  box.innerHTML = list.map(k => {
    const c = _tbCandidates().filter(x => x.view === k)[0];
    if (!c) return '';
    const fixed = k === TABBAR_ANCHOR;                        
    const tip = fixed ? '常驻，不能挪' : '点一下收起 · 按住左右拖换位置';
    return `<button type="button" class="pb-chip${fixed ? ' fixed' : ''}" data-k="${escapeHTML(k)}"`
      + `${fixed ? ' data-fixed="1"' : ''} title="${tip}" aria-pressed="true">`
      + `<span class="pb-chip-i">${c.svg}</span><span class="pb-chip-n">${escapeHTML(c.name)}</span></button>`;
  }).join('');
}

 
 
 
function _barBind(box) {
  if (!box || box.dataset.barBound) return;
  box.dataset.barBound = '1';
  box.addEventListener('pointerdown', e => {
    const ch = e.target.closest('.pb-chip');
    if (!ch || ch.dataset.fixed || _barDrag) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const r = ch.getBoundingClientRect();
    _barDrag = { ch, x0: e.clientX, y0: e.clientY, grab: e.clientX - r.left, moved: false };
    window.addEventListener('pointermove', _barMove, { passive: false });
    window.addEventListener('pointerup', _barUp);
    window.addEventListener('pointercancel', _barUp);
  });
  box.addEventListener('click', e => {
    const ch = e.target.closest('.pb-chip');
    if (!ch || ch.dataset.fixed) return;
    if (Date.now() - _barSkipClickAt < 420) return;    
    if (box.dataset.barMode === 'mock') { _hbSelect(ch.dataset.k); return; }    
    _barToggle(box.dataset.barKind, ch.dataset.k);
  });
}

function _barMove(e) {
  const d = _barDrag;
  if (!d) return;
  if (!d.moved) {
    const dx = e.clientX - d.x0, dy = e.clientY - d.y0;
    if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;           
    if (Math.abs(dy) > Math.abs(dx)) { _barEnd(); return; }     
    d.moved = true;
    d.ch.style.transition = 'none';                             
    d.ch.classList.add('dragging');
  }
  e.preventDefault();
   
  d.ch.style.transform = '';
   
   
   
  const sideBox = _barCrossBox(d.ch, e.clientX);
  if (sideBox && sideBox !== d.ch.parentElement) { sideBox.appendChild(d.ch); sideBox.hidden = false; }
  const layLeft = d.ch.getBoundingClientRect().left;
  d.ch.style.transform = 'translate(' + (e.clientX - d.grab - layLeft) + 'px,0)';
   
  const box = d.ch.parentElement;
  const others = Array.prototype.slice.call(box.children).filter(el => el !== d.ch && el.classList.contains('pb-chip') && !el.hidden);
  let best = null, bd = Infinity;
  others.forEach(el => {
    const r = el.getBoundingClientRect();
    const dd = Math.pow(r.left + r.width / 2 - e.clientX, 2) + Math.pow(r.top + r.height / 2 - e.clientY, 2);
    if (dd < bd) { bd = dd; best = el; }
  });
  if (!best) return;
  const br = best.getBoundingClientRect();
   
  const ref = best.dataset.fixed ? best : (e.clientX > br.left + br.width / 2 ? best.nextElementSibling : best);
  if (ref === d.ch) return;
   
  const before = others.map(el => el.getBoundingClientRect());
  box.insertBefore(d.ch, ref);
  others.forEach((el, i) => {
    const a = before[i], b = el.getBoundingClientRect();
    const dx = a.left - b.left, dy = a.top - b.top;
    if (!dx && !dy) return;
    el.style.transition = 'none';
    el.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
    void el.offsetWidth;
    requestAnimationFrame(() => {
      el.style.transition = 'transform .18s cubic-bezier(.2,.7,.3,1)';
      el.style.transform = '';
    });
  });
}

function _barUp() {
  const d = _barDrag;
  if (!d) return;
  const moved = d.moved;
  const box = d.ch.parentElement;
  const kind = box.dataset.barKind;
  _barEnd();
  if (!moved) return;                        
  _barSkipClickAt = Date.now();
   
   
   
  if (kind === 'head') { _hbDropFromDom(); return; }
  const order = Array.prototype.slice.call(box.children)
    .filter(el => el.classList.contains('pb-chip'))
    .map(el => el.dataset.k).filter(Boolean);
  _barReorder(box.dataset.barKind, order, box.dataset.barSide);
}

 
 
 
function _barCrossBox(ch, x) {
  const host = ch.parentElement;
  if (!host || host.dataset.barKind !== 'head') return null;
  const head = ch.closest('.chat-head');
  if (!head) return null;
  const nm = head.querySelector('.chat-head-name');
  const lb = head.querySelector('.chat-head-left-tools');
  const rb = head.querySelector('.chat-head-tools');
  if (!nm || !lb || !rb) return null;
  const r = nm.getBoundingClientRect();
  if (!r.width) return null;
  if (x < r.left) return lb;
  if (x > r.right) return rb;
  return null;
}

 
 
function _hbDropFromDom() {
  const keys = el => el ? Array.prototype.map.call(el.children, e => e.dataset.k).filter(Boolean) : [];
  const left = keys(document.getElementById('hbPreviewLeft'));
  const right = keys(document.getElementById('hbPreview'));
  const curLeft = _hbLeftList();
  const curRight = _hbList().filter(k => curLeft.indexOf(k) < 0);
  if (left.join(',') === curLeft.join(',') && right.join(',') === curRight.join(',')) return;
  _hbLayoutWrite(left, right);
  renderHeadbar();
  renderHeadBarPanel();
  _layoutChanged();
}

function _barEnd() {
  const d = _barDrag;
  if (!d) return;
  _barDrag = null;
  window.removeEventListener('pointermove', _barMove);
  window.removeEventListener('pointerup', _barUp);
  window.removeEventListener('pointercancel', _barUp);
  d.ch.classList.remove('dragging');
  d.ch.style.transition = '';
  d.ch.style.transform = '';
}

 
 
function _barReorder(kind, order, side) {
  const isHead = kind === 'head';
  const cur = isHead ? _hbList() : _tbList();
  if (isHead) {
    const which = side === 'left' ? 'left' : 'right';
    const leftSet = _hbLeftSet();
    const sideCur = cur.filter(k => (which === 'left') === !!leftSet[k]);
    const nextSide = order.filter(k => sideCur.indexOf(k) >= 0);
    sideCur.forEach(k => { if (nextSide.indexOf(k) < 0) nextSide.push(k); });
    const other = cur.filter(k => sideCur.indexOf(k) < 0);
    const nextLeft = which === 'left' ? nextSide : other;
    const nextRight = which === 'right' ? nextSide : other;
    if (nextLeft.join(',') === (cur.filter(k => !!leftSet[k]).join(','))
      && nextRight.join(',') === (cur.filter(k => !leftSet[k]).join(','))) return;
    _hbLayoutWrite(nextLeft, nextRight);
    renderHeadbar();
    renderHeadBarPanel();
    _layoutChanged();
    return;
  }
  const next = order.filter(k => cur.indexOf(k) >= 0);
  cur.forEach(k => { if (next.indexOf(k) < 0) next.push(k); });
   
  const i = next.indexOf(TABBAR_ANCHOR);
  if (i >= 0) { next.splice(i, 1); next.push(TABBAR_ANCHOR); }
  if (next.join(',') === cur.join(',')) return;
  _tbWrite(next);
  renderTabbar();
  renderTabbarPanel();
  _layoutChanged();
}

 
 
 
function _barToggle(kind, v) {
  if (!v) return;
  if (kind === 'head') {
    const list = _hbList(), i = list.indexOf(v);
    if (i >= 0) list.splice(i, 1);
    else if (list.length >= HEADBAR_MAX) { showToast(`最多 ${HEADBAR_MAX} 枚，先去掉一枚再加`); return; }
    else list.push(v);
    _hbWrite(list);
     
    _hbWriteLeft(_hbLeftList().filter(k => list.indexOf(k) >= 0 && k !== v));
     
     
    _hbSel = i < 0 ? v : (_hbSel === v ? '' : _hbSel);
    renderHeadbar();
    renderHeadBarPanel();
    _hbEnsureActs();    
  } else {
    const list = _tbList(), i = list.indexOf(v);
    if (i >= 0) list.splice(i, 1);
    else if (list.length >= TABBAR_MAX) { showToast(`最多 ${TABBAR_MAX} 枚，先去掉一枚再加`); return; }
    else list.splice(list.length - 1, 0, v);    
    _tbWrite(list);
    renderTabbar();
    renderTabbarPanel();
  }
  _layoutChanged();
}

 
 
 
 
function _hbLeftBox(headEl) {
  let b = document.getElementById('chatHeadLeftTools');
  if (b) return b;
  if (!headEl) return null;
  b = document.createElement('div');
  b.className = 'chat-head-left-tools';
  b.id = 'chatHeadLeftTools';
  b.setAttribute('aria-label', '聊天页顶栏左侧快捷方式');
  const nameEl = headEl.querySelector('.chat-head-name');
  headEl.insertBefore(b, nameEl || headEl.firstChild);
  return b;
}

 
 
 
 
 
 
 
 
 
 
 
 
const HB_DENS = [
  { box: 36, gap: 8, quick: 30 },
  { box: 32, gap: 6, quick: 28 }
];
const HB_PAD_W = 28, HB_COL_GAP = 12, HB_SLOT_W = 36, HB_LEFT_LEAD = 44, HB_NAME_FLOOR = 40;
 
let _hbLastW = 0;
function _hbBoxW(k, d) { return HB_QUICK[k] ? d.quick : d.box; }
function _hbRowW(keys, d) {
  let n = 0;
  keys.forEach((k, i) => { n += _hbBoxW(k, d) + (i ? d.gap : 0); });
  return n;
}
function _hbLeftColW(keys, d) { return keys.length ? HB_LEFT_LEAD + _hbRowW(keys, d) : HB_SLOT_W; }
 
function _hbNeedW(leftKeys, rightKeys, d, more) {
  const r = _hbRowW(rightKeys, d) + (more ? (rightKeys.length ? d.gap : 0) + d.box : 0);
  return HB_PAD_W + HB_COL_GAP + Math.max(HB_SLOT_W, _hbLeftColW(leftKeys, d)) + r + HB_NAME_FLOOR;
}
function _hbMeasure(el) {
  const w = el ? el.clientWidth : 0;
  if (w > 0) { _hbLastW = w; return w; }
  if (_hbLastW) return _hbLastW;
  const shell = document.querySelector('.app-shell');
  return (shell && shell.clientWidth) || Math.min(window.innerWidth || 390, 480);
}
 
function _hbMeasureMock(el) {
  const w = el ? el.clientWidth : 0;
  return w > 0 ? w : 336;
}
 
function _hbPlan(leftKeys, rightKeys, width) {
  const l = leftKeys.slice(), r = rightKeys.slice();
  for (let i = 0; i < HB_DENS.length; i++) {
    const d = HB_DENS[i];
    if (_hbNeedW(l, r, d, false) <= width) return { d, left: l, right: r, over: [] };
  }
  const d = HB_DENS[HB_DENS.length - 1], over = [];
  let guard = 0;
   
  while (_hbNeedW(l, r, d, true) > width && (r.length || l.length) && guard++ < 80) {
    over.unshift(r.length ? r.pop() : l.pop());
  }
  return { d, left: l, right: r, over };
}
 
function _hbMoreParts(headEl, box) {
  let btn = box.querySelector('[data-hb-more]');
  if (!btn) {
    btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'icon-btn hb-more-btn';
    btn.dataset.hbMore = '1';
    btn.title = '还有几枚放不下：点开看';
    btn.setAttribute('aria-label', '还有几枚放不下的快捷方式');
    btn.setAttribute('aria-haspopup', 'menu');
    btn.innerHTML = '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor" aria-hidden="true">'
      + '<circle cx="12" cy="5" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="12" cy="19" r="1.7"/></svg>';
    box.appendChild(btn);
  }
  let pop = headEl.querySelector('[data-hb-more-pop]');
  if (!pop) {
    pop = document.createElement('div');
    pop.className = 'hb-more-pop';
    pop.dataset.hbMorePop = '1';
    pop.setAttribute('role', 'menu');
    pop.setAttribute('aria-label', '放不下的快捷方式');
    pop.hidden = true;
    headEl.appendChild(pop);
  }
  return { btn, pop };
}
 
 
 
function _hbApplyPlan(headEl, box, leftBox, plan) {
  const d = plan.d;
  headEl.style.setProperty('--hb-box', d.box + 'px');
  headEl.style.setProperty('--hb-gap', d.gap + 'px');
  const leftW = Math.max(HB_SLOT_W, _hbLeftColW(plan.left, d));
  const rightW = _hbRowW(plan.right, d);
  const moreW = plan.over.length ? (plan.right.length ? d.gap : 0) + d.box : 0;
  const nameMax = Math.max(HB_NAME_FLOOR, Math.min(260, _hbMeasure(headEl) - HB_PAD_W - HB_COL_GAP - leftW - rightW - moreW));
  headEl.style.setProperty('--hb-name-max', nameMax + 'px');
   
  headEl.style.setProperty('--hb-sidew', Math.max(leftW, rightW + moreW) + 'px');
  const overSet = {};
  plan.over.forEach(k => { overSet[k] = 1; });
  const hideIn = host => {
    if (!host) return;
    Array.prototype.forEach.call(host.children, el => {
      if (!el.dataset.hbKey) return;
      el.hidden = !!overSet[el.dataset.hbKey];
    });
  };
  hideIn(leftBox);
  hideIn(box);
  const parts = _hbMoreParts(headEl, box);
   
  if (parts.btn.parentNode === box && box.lastElementChild !== parts.btn) box.appendChild(parts.btn);
  parts.btn.hidden = plan.over.length === 0;
  if (plan.over.length === 0) { parts.pop.hidden = true; parts.pop.innerHTML = ''; }
  else {
    const order = _hbList();
    parts.pop.innerHTML = order.filter(k => overSet[k]).map(k => {
      const c = _hbCand(k);
      if (!c) return '';
      return '<button type="button" class="hb-more-row" role="menuitem" data-hb-more-key="' + escapeHTML(k) + '">'
        + '<span class="hb-more-ic">' + c.svg + '</span><span class="hb-more-n">' + escapeHTML(c.name) + '</span></button>';
    }).join('');
    parts.pop.hidden = true;
  }
  if (leftBox) leftBox.hidden = plan.left.length === 0;    
  return plan.over;
}
 
 
 
 
function _hbEnsureActs() {
  const acts = document.getElementById('hbActs');
  const m = document.getElementById('layoutMask');
  if (!acts || acts.hidden || !m || m.hidden) return;
  const body = m.querySelector('.fs-sheet-body');
  if (!body) return;
  if (acts.getBoundingClientRect().top < body.getBoundingClientRect().top + 8) acts.scrollIntoView({ block: 'start' });
}
 
function _hbMoreBind(headEl) {
  if (!headEl || headEl.dataset.hbMoreBound) return;
  headEl.dataset.hbMoreBound = '1';
  headEl.addEventListener('click', e => {
    const pop = headEl.querySelector('[data-hb-more-pop]');
    if (e.target.closest('[data-hb-more]')) {
      if (pop) pop.hidden = !pop.hidden;
      return;
    }
    const row = e.target.closest('[data-hb-more-key]');
    if (!row || !pop || !pop.contains(row)) return;
    const k = row.dataset.hbMoreKey;
    pop.hidden = true;
    const node = headEl.querySelector('[data-hb-key="' + k + '"]');
    if (node) node.click();
    else if (k.charAt(0) === '#' && typeof _hubRoute === 'function') _hubRoute(k);
    else if (typeof showView === 'function') showView(k);
  });
}
 
document.addEventListener('click', e => {
  if (e.target.closest('[data-hb-more]') || e.target.closest('[data-hb-more-pop]')) return;
  $$('[data-hb-more-pop]').forEach(p => { if (!p.hidden) p.hidden = true; });
}, true);
 
 
let _hbFitT = 0;
function _hbRefitSoon() {
  clearTimeout(_hbFitT);
  _hbFitT = setTimeout(() => {
    try { renderHeadbar(); } catch (e) {}
    const m = document.getElementById('layoutMask');
    if (m && !m.hidden) { try { _hbMockPaint(); } catch (e) {} }
  }, 180);
}
window.addEventListener('resize', _hbRefitSoon);
window.addEventListener('orientationchange', _hbRefitSoon);
if (window.visualViewport) { try { window.visualViewport.addEventListener('resize', _hbRefitSoon); } catch (e) {} }

function renderHeadbar() {
  const box = document.querySelector('#chatView .chat-head-tools');
  if (!box) return;
  _hbBuiltins();
  _hbUnseedQuick();                                
  const headEl = box.closest('.chat-head');
  const leftBox = _hbLeftBox(headEl);
  const list = _hbList(), keep = {}, leftSet = _hbLeftSet();
  list.forEach(k => { keep[k] = 1; });
  [leftBox, box].forEach(host => {
    if (!host) return;
    Array.prototype.slice.call(host.children).forEach(el => {
      if (el.dataset.hbMore) return;                
      const k = el.dataset.hbKey || '';
      if (keep[k]) return;
      if (!el.dataset.hbCustom) _hbPool[k] = el;    
      el.remove();
    });
  });
   
  const findNode = k => {
    for (const host of [leftBox, box]) {
      if (!host) continue;
      const n = host.querySelector('[data-hb-key="' + k + '"]');
      if (n) return n;
    }
    return null;
  };
  list.forEach(k => {
    let node = _hbPool[k] || findNode(k);
    delete _hbPool[k];
    if (!node) {
      const c = _hbCandidates().filter(x => x.key === k)[0];
      if (!c) return;
      node = document.createElement('button');
      node.type = 'button';
      node.className = 'icon-btn hb-custom' + (HB_QUICK[k] ? ' hb-quick' : '');
      node.dataset.hbCustom = '1';
      node.dataset.hbKey = k;
      node.title = c.name;
      node.setAttribute('aria-label', c.name);
      node.innerHTML = c.svg;
    }
    node.hidden = false;
    (leftSet[k] ? leftBox : box).appendChild(node);
  });
   
   
  const leftKeys = list.filter(k => leftSet[k]);
  const rightKeys = list.filter(k => !leftSet[k]);
  if (headEl) {
    _hbMoreBind(headEl);
    _hbApplyPlan(headEl, box, leftBox, _hbPlan(leftKeys, rightKeys, _hbMeasure(headEl)));
     
    headEl.setAttribute('data-hb-namepos', hbNamePos());
  }
   
  if (typeof renderChatSwitchPanel === 'function') renderChatSwitchPanel();
}

function renderHeadBarPanel() {
  const list = $('#hbList');
  if (!list) return;
  const cur = _hbList(), on = {};
  cur.forEach(k => { on[k] = 1; });
   
   
   
  if ($('#chatLeftChips')) {
    const leftPref = (typeof chatLeftPref === 'function') ? chatLeftPref() : 'back';
    $$('#chatLeftChips .fchip').forEach(c => {
      const sel = c.dataset.chatleft === leftPref;
      c.classList.toggle('on', sel);
      c.setAttribute('aria-pressed', sel ? 'true' : 'false');
    });
  }
   
   
  if ($('#chatNamePosChips')) {
    const pos = hbNamePos();
    $$('#chatNamePosChips .fchip').forEach(c => {
      const sel = c.dataset.namepos === pos;
      c.classList.toggle('on', sel);
      c.setAttribute('aria-pressed', sel ? 'true' : 'false');
    });
  }
   
  _hbMockPaint();
  _hbActsPaint();
   
   
   
  const leftSet = _hbLeftSet();
  const all = _hbCandidates(), inBar = [], rest = [];
  cur.forEach(k => { const c = all.filter(x => x.key === k)[0]; if (c) inBar.push(c); });
  all.forEach(c => { if (!on[c.key]) rest.push(c); });
  const rowOf = c => {
     
     
    const where = on[c.key] ? `<span class="tb-lock">名字${leftSet[c.key] ? '左' : '右'}边</span>` : '';
    const right = `${where}<span class="hub-tg${on[c.key] ? '' : ' off'}"></span>`;
    const body = `<span class="tb-ico">${c.svg}</span><span class="tb-name">${c.name}</span>${right}`;
    return `<button type="button" class="tb-row" data-hb-view="${c.key}" aria-pressed="${on[c.key] ? 'true' : 'false'}">${body}</button>`;
  };
  list.innerHTML =
    (inBar.length ? `<div class="tb-group-t">在顶栏上<i>${inBar.length}/${HEADBAR_MAX}</i></div>` + inBar.map(rowOf).join('') : '')
    + (rest.length ? `<div class="tb-group-t add" data-hb-add-group="1">可以放上顶栏</div>` + rest.map(rowOf).join('') : '');
  const note = $('#hbNote');
  if (note) {
    const callOut = (typeof _callInHeadbar === 'function' && !_callInHeadbar());
    const leftSwitch = (typeof chatLeftPref === 'function' && chatLeftPref() === 'switch');
    note.textContent = (cur.length >= HEADBAR_MAX
      ? `顶栏已放 ${HEADBAR_MAX} 枚（上限）——想换别的，点栏上那枚再按「收起来」。`
      : `顶栏放 ${cur.length}/${HEADBAR_MAX} 枚。`)
      + '手机屏窄、这一排放不下时，靠边的几枚会自动收进顶栏末尾的 ⋯（不删、不丢，点开就能用）。'
       
       
      + '点栏上的图标＝选中它；按住左右拖换位置，拖过名字就换到另一边。'
       
       
      + (callOut
        ? (leftSwitch
          ? '　⚠ 通话已从顶栏收起：这会儿从聊天页左上的「会话」面板里进。'
          : '　⚠ 通话已收起，而左上角是「返回列表」：聊天页上暂时没法打电话——把「打电话」放回顶栏，或把左上角改成「会话」。')
        : '');
  }
}

 
 
 
 
 
 
 
 
 
 
 
 
 
let _hbSel = '';               
function _hbCand(k) {
  const list = _hbCandidates();
  for (let i = 0; i < list.length; i++) { if (list[i].key === k) return list[i]; }
  return null;
}
function _hbSelect(k) {
  if (!k) return;
  _hbSel = _hbSel === k ? '' : k;       
  _hbMockPaint();
  _hbActsPaint();
  _hbEnsureActs();
}
 
 
let _hbAddFlashT = 0;
function _hbFocusAdd() {
  const box = document.getElementById('hbList');
  if (!box) return;
  const group = box.querySelector('[data-hb-add-group]');
  if (!group) { showToast('能放的都放上去了'); return; }
  group.scrollIntoView({ block: 'center', behavior: 'smooth' });
  box.classList.add('is-flash');
  clearTimeout(_hbAddFlashT);
  _hbAddFlashT = setTimeout(() => box.classList.remove('is-flash'), 1400);
}
function _hbMockPaint() {
  const mock = document.getElementById('hbMock');
  if (!mock) return;
  const bar = mock.querySelector('.chat-head');
  const list = _hbList(), leftSet = _hbLeftSet();
  const leftN = list.filter(k => leftSet[k]).length;
  const leftKeys = list.filter(k => leftSet[k]);
  const rightKeys = list.filter(k => !leftSet[k]);
  if (_hbSel && list.indexOf(_hbSel) < 0) _hbSel = '';      
   
   
  const plan = _hbPlan(leftKeys, rightKeys, _hbMeasureMock(bar));
  const overSet = {};
  plan.over.forEach(k => { overSet[k] = 1; });
  if (bar) {
    bar.setAttribute('data-hb-namepos', hbNamePos());
    bar.style.setProperty('--hb-box', plan.d.box + 'px');
    bar.style.setProperty('--hb-gap', plan.d.gap + 'px');
    const lw = Math.max(HB_SLOT_W, _hbLeftColW(plan.left, plan.d));
    const rw = _hbRowW(plan.right, plan.d);
    const mw = plan.over.length ? (plan.right.length ? plan.d.gap : 0) + plan.d.box : 0;
    bar.style.setProperty('--hb-name-max', Math.max(HB_NAME_FLOOR, Math.min(180, _hbMeasureMock(bar) - HB_PAD_W - HB_COL_GAP - lw - rw - mw)) + 'px');
    bar.style.setProperty('--hb-sidew', Math.max(lw, rw + mw) + 'px');
  }
   
  const slot = document.getElementById('hbmLeft'), real = document.getElementById('chatSwitchBtn');
  if (slot) {
    slot.innerHTML = real ? real.innerHTML : '';
    slot.title = '左上角那枚：' + (chatLeftPref() === 'switch' ? '切换会话' : '返回列表') + '（点这里换）';
    slot.setAttribute('aria-label', slot.title);
  }
  const nm = document.getElementById('hbmName');
  if (nm) {
    nm.textContent = (typeof chatPartnerName === 'function' ? chatPartnerName() : '') || 'TA';
    nm.title = '名字站在哪：' + (hbNamePos() === 'left' ? '靠左' : '居中') + '（点这里换）';
  }
   
   
  const who = (typeof currentContact === 'function' ? currentContact() : null);
  const avP = document.getElementById('hbmAvP'), avM = document.getElementById('hbmAvM');
  if (avP) avP.innerHTML = (typeof avatarHTML === 'function') ? avatarHTML(who && typeof chatAvatarOf === 'function' ? chatAvatarOf(who) : '') : '';
  if (avM) avM.innerHTML = (typeof avatarHTML === 'function') ? avatarHTML(typeof chatMyAvatar === 'function' ? chatMyAvatar() : '') : '';
  [['hbPreviewLeft', 'left'], ['hbPreview', 'right']].forEach(pair => {
    const box = document.getElementById(pair[0]);
    if (!box) return;
    box.dataset.barKind = 'head';
    box.dataset.barSide = pair[1];
    box.dataset.barMode = 'mock';
    _barBind(box);
    const keys = list.filter(k => (pair[1] === 'left') === !!leftSet[k]);
     
     
     
    box.hidden = pair[1] === 'left' ? plan.left.length === 0 : false;
     
     
     
     
     
    box.innerHTML = keys.map(k => {
      const c = _hbCand(k);
      if (!c) return '';
      return `<button type="button" class="icon-btn pb-chip${HB_QUICK[k] ? ' hb-quick' : ''}${k === _hbSel ? ' sel' : ''}" data-k="${escapeHTML(k)}"`
        + (overSet[k] ? ' hidden' : '')
        + ` title="${escapeHTML(c.name)}（点这里选中）" aria-label="${escapeHTML(c.name)}">${c.svg}</button>`;
    }).join('') + (pair[1] === 'right'
      ? (plan.over.length
        ? '<button type="button" class="icon-btn hb-more-mini" data-hb-more="1" title="放不下的 ' + plan.over.length + ' 枚：见下面那行" aria-label="放不下的快捷方式">'
          + '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true"><circle cx="12" cy="5" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="12" cy="19" r="1.7"/></svg></button>'
        : (list.length < HEADBAR_MAX
          ? '<button type="button" class="icon-btn hb-add" data-hb-add="1" title="添加一枚功能" aria-label="添加功能">'
            + '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg></button>'
          : ''))
      : '');
  });
   
   
  const tip = document.getElementById('hbOverTip');
  if (tip) {
    if (plan.over.length) {
      tip.hidden = false;
      tip.textContent = '这台手机上放不下 ' + plan.over.length + ' 枚（'
        + plan.over.map(k => { const c = _hbCand(k); return c ? c.name : k; }).join(' · ')
        + '）：聊天页会把它们收进右上角的 ⋯，点开就能用。想都摆在外面，把其中几枚拖到名字左边、或在下面「收起来」。';
    } else {
      tip.hidden = true;
      tip.textContent = '';
    }
  }
}
 
 
function _hbActsPaint() {
  const box = document.getElementById('hbActs');
  if (!box) return;
  const k = _hbSel, list = _hbList();
  if (!k || list.indexOf(k) < 0) { box.hidden = true; box.innerHTML = ''; return; }
  const c = _hbCand(k), name = c ? c.name : k;
  const leftSet = _hbLeftSet(), isLeft = !!leftSet[k];
  const side = list.filter(x => !!leftSet[x] === isLeft);
  const i = side.indexOf(k);
  box.hidden = false;
  box.innerHTML = `<span class="hb-acts-t">${escapeHTML(name)} · 名字${isLeft ? '左' : '右'}边 ${i + 1}/${side.length}</span>`
    + `<button type="button" class="hb-act" data-hb-act="prev"${i <= 0 ? ' disabled' : ''}>◀ 往前挪</button>`
    + `<button type="button" class="hb-act" data-hb-act="next"${i >= side.length - 1 ? ' disabled' : ''}>往后挪 ▶</button>`
    + `<button type="button" class="hb-act" data-hb-act="side">挪到名字${isLeft ? '右' : '左'}边</button>`
    + `<button type="button" class="hb-act del" data-hb-act="drop">收起来</button>`;
}

 
$('#hbList') && $('#hbList').addEventListener('click', e => {
  const row = e.target.closest('[data-hb-view]');
  if (!row) return;
  _barToggle('head', row.dataset.hbView);
});

 
 
$('#hbMock') && $('#hbMock').addEventListener('click', e => {
  if (Date.now() - _barSkipClickAt < 420) return;             
  if (e.target.closest('[data-hb-add]')) { _hbFocusAdd(); return; }    
  if (e.target.closest('[data-hb-more]')) {                           
    const tip = document.getElementById('hbOverTip');
    if (tip && !tip.hidden) tip.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    return;
  }
  if (e.target.closest('.pb-chip')) return;                    
  if (e.target.closest('#hbmLeft')) {
    if (typeof chatLeftSet !== 'function') return;
    chatLeftSet(chatLeftPref() === 'back' ? 'switch' : 'back');
    renderHeadBarPanel();
    _layoutChanged();
    return;
  }
  if (e.target.closest('#hbmName')) { hbNamePosSet(hbNamePos() === 'center' ? 'left' : 'center'); return; }
  if (_hbSel) { _hbSel = ''; _hbMockPaint(); _hbActsPaint(); }    
});

 
 
$('#hbActs') && $('#hbActs').addEventListener('click', e => {
  const b = e.target.closest('[data-hb-act]');
  if (!b || b.disabled || !_hbSel) return;
  const act = b.dataset.hbAct, k = _hbSel, isLeft = !!_hbLeftSet()[k];
  if (act === 'side') _hbSetSide(k, isLeft ? 'right' : 'left');
  else if (act === 'drop') { _hbSel = ''; _barToggle('head', k); }
  else _hbMoveSide(k, act === 'prev' ? -1 : 1);
});

 
 
$('#csHeadBarBtn') && $('#csHeadBarBtn').addEventListener('click', () => {
  if (typeof closeChatSwitch === 'function') closeChatSwitch();
  openLayoutPanel('head');
});

 
 
 
 
 
 
