function divineKeyOf(c) { return c.deck === 'lenormand' ? 'l' + c.num : c.id; }
 
 
 
const _LENO_ART_VER = 4;    
 
 
 
 
 
 
 
const DIVINE_ART2X = { lenormand: 'img/leno2x' };
const _LENO_ART2X_VER = 1;   
function divineArtOf(c, hi) {
  const use2x = !!(hi && DIVINE_ART2X[c.deck]);
  const v = c.deck === 'lenormand' ? '?v=' + (use2x ? _LENO_ART2X_VER : _LENO_ART_VER) : '';
  return (use2x ? DIVINE_ART2X[c.deck] : DIVINE_ART[c.deck]) + '/' + (c.deck === 'lenormand' ? c.num : c.id) + '.webp' + v;
}
 
function divineArtHi(c) { return DIVINE_ART2X[c.deck] ? divineArtOf(c, true) : ''; }
const divineCard = (key) => DIVINE_BY_KEY[key] || null;
 
 
 
 
 
 
const divineSpread = (id, n) => {
  const hit = DIVINE_SPREADS.filter(s => s.id === id)[0] || null;
  if (!(n > 0)) return hit || DIVINE_SPREADS[0];
  if (hit && (hit.n === null || hit.n === n)) return hit;       
  const byN = DIVINE_SPREADS.filter(s => s.n === n)[0];
  return byN || DIVINE_SPREADS.filter(s => s.id === 'free')[0] || DIVINE_SPREADS[0];
};
 
const divineSpreadsOf = () => DIVINE_SPREADS;
 
 
 
 
 
 
 
 
 
 
 
 
 
