function _dvNCount(v, dflt) {
  const n = Number(v);
  return (isFinite(n) && v !== '' && v !== null) ? Math.max(1, Math.min(DV_FREE_MAX, Math.round(n))) : dflt;
}
 
 
 
 
 
 
 
const DVTA_SPREAD_IDS = ['free', 1, 3, 5];
function _dvTaSpreadOk(v) { return v === 'free' || [1, 3, 5].indexOf(Number(v)) >= 0; }
 
 
function _dvTaMixSet(v) {
  const arr = Array.isArray(v) ? v : [];
  const out = DVTA_SPREAD_IDS.filter(id => arr.some(x => String(x) === String(id)));
  return out.length ? out : DVTA_SPREAD_IDS.slice();
}
function dvTaCfg(cid) {
  const by = (data && data.dvTaBy && typeof data.dvTaBy === 'object') ? data.dvTaBy : {};
  const src = (cid && by[cid] && typeof by[cid] === 'object') ? by[cid] : {};
  const deck = (src.deck === 'tarot' || src.deck === 'lenormand') ? src.deck : 'both';
   
   
   
  let n = src.n;
  if (n === 'mix' && !Array.isArray(src.mixSet)) n = 'free';
  if (n !== 'mix' && n !== 'free') n = _dvTaSpreadOk(n) ? Number(n) : 'free';
  const p = Number(src.prob);
   
  const lo = _dvNCount(src.nMin, 1), hi = _dvNCount(src.nMax, 5);
  return { on: src.on === true, deck: deck, n: n, prob: isFinite(p) ? Math.max(0, Math.min(100, p)) : 15,
    nMin: Math.min(lo, hi), nMax: Math.max(lo, hi), mixSet: _dvTaMixSet(src.mixSet) };
}

 
 
function _dvPileKeys(deck) {
  const list = deck === 'tarot' ? DIVINE_PILES.tarot
    : deck === 'lenormand' ? DIVINE_PILES.lenormand
    : DIVINE_PILES.lenormand.concat(DIVINE_PILES.tarot);
  return _dvShuffle(list).map(divineKeyOf);
}

 
 
 
 
 
function dvTaDrawN(cfg) {
  if (cfg.n !== 'mix') return cfg.n === 'free' ? _dvTaRangeN(cfg) : Number(cfg.n);
  const set = (Array.isArray(cfg.mixSet) && cfg.mixSet.length) ? cfg.mixSet : DVTA_SPREAD_IDS;
  const pick = set[Math.min(set.length - 1, _dvRand(set.length))];
  return pick === 'free' ? _dvTaRangeN(cfg) : Number(pick);
}
function _dvTaRangeN(cfg) {
  const lo = Math.min(cfg.nMin, cfg.nMax), hi = Math.max(cfg.nMin, cfg.nMax);
  return lo + _dvRand(hi - lo + 1);
}
 
 
 
function dvTaDraw(cfg) {
  const n = dvTaDrawN(cfg);
  const sp = divineSpread('', n);
  const pile = _dvPileKeys(cfg.deck);
  const cards = pile.slice(0, n).map(k => {
    const card = divineCard(k);
    const p = { k: k };
    if (card && card.deck === 'tarot') p.u = _dvRand(2) === 0;
    return p;
  });
  return { at: Date.now(), q: '', sp: sp.id, cards: cards };
}

 
 
 
function dvTaMaybeSend(cid) {
  try {
    if (!cid) return false;
    if (typeof _chatIsGroup === 'function' && _chatIsGroup(cid)) return false;
     
     
     
    if (typeof vcCardNarrow === 'function' && vcCardNarrow(cid)) return false;
    const cfg = dvTaCfg(cid);    
    if (!cfg.on || !(cfg.prob > 0)) return false;
    if (!_rand(cfg.prob)) return false;
    const rec = dvTaDraw(cfg);
    if (!rec.cards.length) return false;
     
     
     
     
    rec.by = 'ta';
    const msg = {
      id: nextId(), from: 'partner', unread: true,
      src: 'dv',             
                             
                             
      dv: rec                
    };
    _deliverToChat(msg, cid);
    return true;
  } catch (e) { return false; }
}
 
 
 
 
 
