const DEAL_COLS = 3;
const DEAL_ROWS = 5;         
 
 
const DEAL_EXTRA = 1;
const DEAL_MAX = 8;          
const DEAL_LP_MS = 500;      
const DEAL_TA_WAIT = 900;    
 
 
 
 
