async function saveBehaviorNow() {
   
   
   
   
  const _bt = (typeof mateBhTarget === 'function') ? mateBhTarget() : { book: data.behavior || {}, mem: false };
  const _mem = !!_bt.mem;
  const bh = _bt.book || {};
   
   
   
  const _as = (typeof mateAsTarget === 'function') ? mateAsTarget() : { cid: data.activeChat, book: bh };
   
   
  const _bhBefore = JSON.stringify(bh);
  const _asBefore = JSON.stringify(_as.book);    
  const _batchBefore = !!data.batchSend;
  const _voiceBefore = data.voiceSend === true;    
  const _videoBefore = data.videoSend === true;    
   
   
   
   
   
   
  const num = (id, min, max, book) => {
    const raw = numInputText($(id).value);
    if (raw === '') {
      const cur = (book || bh)[id.replace(/^#/, '')];
      return (typeof cur === 'number' && isFinite(cur)) ? Math.max(min, Math.min(max, cur)) : min;
    }
    const v = Number(raw);
    return Math.max(min, Math.min(max, Number.isFinite(v) ? v : min));
  };
   
  const keep = (id, min, max) => { const raw = numInputText($(id).value); return raw === '' ? null : num(id, min, max); };
  bh.rnProb = num('#rnProb', 0, 100);
  bh.strayProb = num('#strayProb', 0, 100);    
   
   
  bh.referProb = num('#referProb', 0, 100);
  bh.meantProb = num('#meantProb', 0, 100);
  bh.rsMin = num('#rsMin', 1, 3600);
  bh.rsMax = Math.max(bh.rsMin, num('#rsMax', 1, 3600));
   
   
   
   
   
   
  const _rpMin = keep('#replyMin', 1, 10), _rpMax = keep('#replyMax', 1, 10);
  if (_rpMin !== null) bh.replyMin = _rpMin;
  bh.replyMax = Math.max(bh.replyMin, _rpMax === null ? (Number(bh.replyMax) || bh.replyMin) : _rpMax);
  bh.pyEnabled = $('#pyEnabled').checked;
   
   
   
   
  if (!_mem && !bh.pyEnabled && data.chatSettings) for (const _cid in data.chatSettings) { const _cb = data.chatSettings[_cid]; if (_cb && typeof _cb === 'object') _cb.pyEnabled = false; }
  bh.tsEnabled = $('#tsEnabled').checked;
   
   
   
  bh.tsMin = num('#tsMin', 1, 10);
  bh.tsMax = Math.max(bh.tsMin, num('#tsMax', 1, 10));
  bh.meMerge = $('#meMergeSend').checked;    
  bh.enterSend = $('#enterSend').checked;
   
   
  if (!_mem) {
    data.batchSend = $('#batchSend').checked;    
    data.voiceSend = $('#voiceSend').checked;    
    data.videoSend = $('#videoSend').checked;    
  }
  bh.pyProb = num('#pyProb', 0, 100);
  bh.pyMin = num('#pyMin', 1, 20);
  bh.pyMax = Math.max(bh.pyMin, num('#pyMax', 1, 20));
  bh.pyPunctEnabled = $('#pyPunctEnabled').checked;    
  bh.csNormal = $('#csNormal').checked;
  bh.csTriggerName = $('#csTriggerName').checked;
  bh.touchProb = num('#touchProb', 0, 100);
  bh.stickerProb = num('#stickerProb', 0, 100);
  bh.emojiProb = num('#emojiProb', 0, 100);
  bh.kaomojiProb = num('#kaomojiProb', 0, 100);
  bh.imageProb = num('#imageProb', 0, 100);
  bh.voiceProb = num('#voiceProb', 0, 100);
  bh.quoteProb = num('#quoteProb', 0, 100);
  bh.rcProb = num('#rcProb', 0, 100);
  bh.rcRefix = num('#rcRefix', 0, 100);
   
  bh.recallEnabled = !$('#recallEnable').checked;
   
   
   
   
  const _ax = _as.book;
  _ax.asEnabled = $('#asEnabled').checked;
  _ax.asProb = num('#asProb', 0, 100, _ax);
  _ax.asMin = num('#asMin', 1, 720, _ax);
  _ax.asMax = Math.max(_ax.asMin, num('#asMax', 1, 720, _ax));
  _ax.asCountMin = num('#asCountMin', 1, 10, _ax);
  _ax.asCountMax = Math.max(_ax.asCountMin, num('#asCountMax', 1, 10, _ax));
  _ax.dndEnabled = $('#dndEnabled').checked;
  _ax.asByState = $('#asByState').checked;
  bh.rnByState = $('#rnByState').checked;    
  bh.rnOn = $('#rnOn').checked;              
  bh.strayOn = $('#strayOn').checked;        
  _ax.asBadge = $('#asBadge').checked;
  _ax.asGroupProb = num('#asGroupProb', 0, 100, _ax);
   
   
   
   
  const _bhPrev = JSON.parse(_bhBefore);
  let _replyChanged = false;
  if (_mem) {
    for (const k of GBH_KEYS) {
      if (JSON.stringify(bh[k]) !== JSON.stringify(_bhPrev[k])) { mateBhSet(k, bh[k]); _replyChanged = true; }
    }
  } else {
    data.behavior = bh;
  }
   
   
  await flushSave();
   
   
  if (typeof rescheduleActiveSend === 'function') rescheduleActiveSend(_as.cid);
  if (typeof _syncBatchBtn === 'function') _syncBatchBtn();    
  if (typeof _syncVoiceBtn === 'function') _syncVoiceBtn();    
  if (typeof _syncVideoBtn === 'function') _syncVideoBtn();    
  renderProfile();
   
   
  return (_mem ? _replyChanged : (JSON.stringify(bh) !== _bhBefore)) || JSON.stringify(_as.book) !== _asBefore
    || (!_mem && !!data.batchSend !== _batchBefore) || (!_mem && (data.voiceSend === true) !== _voiceBefore)
    || (!_mem && (data.videoSend === true) !== _videoBefore);
}

 
