function _autoSaveCard(containerSel, saveFn, savedText) {
  const card = $(containerSel);
  if (!card) return;
  let timer;
  const queue = () => {
    clearTimeout(timer);
    timer = setTimeout(async () => {
      const changed = await saveFn();
      if (typeof renderFoldSummaries === 'function') renderFoldSummaries();
      if (changed) autoSaveToast(savedText);
    }, 400);
  };
  card.addEventListener('input', queue);
  card.addEventListener('change', queue);
}
