function _askMasterSet(field, v) {
  if (field !== 'referOn' && field !== 'meantOn') return false;
  const on = v === true;
  if (data[field] === on) return false;
  data[field] = on;
  save();
  if (typeof resetMessageRender === 'function') resetMessageRender();
  if (typeof renderMessages === 'function') renderMessages();
  if (typeof renderProfile === 'function') renderProfile();                         
  if (typeof renderFoldSummaries === 'function') renderFoldSummaries();             
  if (typeof renderHubPage === 'function') renderHubPage();                         
  return true;
}
 
