var _callBgCid = '';
function _callBgMap() {
  if (!data.callSettings) data.callSettings = {};
  const m = data.callSettings.callBgByCid;
  if (!m || typeof m !== 'object' || Array.isArray(m)) data.callSettings.callBgByCid = {};
  return data.callSettings.callBgByCid;
}
 
function _callBgTarget() {
  const list = (typeof soloCandidates === 'function') ? soloCandidates() : ((data.contacts || []).filter(c => c && c.id && c.kind !== 'group'));
  if (!_callBgCid || !list.some(c => c.id === _callBgCid)) {
    _callBgCid = (data.activeChat && list.some(c => c.id === data.activeChat))
      ? data.activeChat : (list[0] ? list[0].id : '');
  }
  return _callBgCid;
}
 
function renderCallBgUI() {
  const list = (typeof soloCandidates === 'function') ? soloCandidates() : [];
  const cid = _callBgTarget();
  const nm = (cid && typeof _soloName === 'function') ? _soloName(cid) : '';
  const row = $('#callBgRow');
  if (row) {
    const key = list.map(c => c.id).join(',');
    if (row.getAttribute('data-ids') !== key) {    
      row.setAttribute('data-ids', key);
      row.innerHTML = list.map(c => '<button type="button" class="contact-chip" data-callbgcid="' + escapeHTML(c.id) + '">' + escapeHTML(_soloName(c.id)) + '</button>').join('');
      row.hidden = !list.length;
    }
    Array.prototype.forEach.call(row.querySelectorAll('[data-callbgcid]'), b => {
      b.classList.toggle('active', b.getAttribute('data-callbgcid') === cid);
    });
  }
  const src = (cid && _callBgMap()[cid]) || '';
  const prev = $('#callBgPreview');
  if (prev) {
    prev.style.backgroundImage = src ? 'url("' + src + '")' : '';
    prev.textContent = !list.length ? '还没有单聊联系人' : (src ? '' : (nm ? '「' + nm + '」未设置' : '未设置背景图'));
  }
  const up = $('#callBgUpload'), clr = $('#callBgClear'), inp = $('#callBgInput');
  if (up) up.disabled = !cid;
  if (inp) inp.disabled = !cid;
  if (clr) clr.disabled = !cid || !src;
   
  if (typeof applyCallBg === 'function') applyCallBg(cid);
}

(function _bindCallBg() {
  const up = $('#callBgUpload'), inp = $('#callBgInput'), clr = $('#callBgClear'), row = $('#callBgRow'), th = $('#callBgPreview');
  if (!up || !inp) return;
   
  if (th) {
    th.title = '点开看整屏效果';
    th.onclick = () => { if (typeof previewCallBg === 'function') previewCallBg(_callBgTarget()); };
  }
  if (row) row.onclick = e => {
    const b = e.target.closest && e.target.closest('[data-callbgcid]');
    if (!b || !row.contains(b)) return;
    _callBgCid = b.getAttribute('data-callbgcid');
    renderCallBgUI();
  };
  up.onclick = () => inp.click();
  inp.onchange = async e => {
    e.stopPropagation();                       
    const f = e.target.files && e.target.files[0];
    if (!f) return;
    const cid = _callBgTarget();
    if (!cid) { e.target.value = ''; if (typeof showToast === 'function') showToast('先在通讯录里加一位单聊联系人'); return; }
    const img = await fileData(f, _bgUploadEdge(), 0.82);
    e.target.value = '';
    if (!img) return;                          
    _callBgMap()[cid] = img;
    renderCallBgUI();
    await flushSave();
    if (typeof renderFoldSummaries === 'function') renderFoldSummaries();
    if (typeof showToast === 'function') showToast('已换「' + (_soloName(cid) || '这位') + '」的通话背景');
  };
  if (clr) clr.onclick = async () => {
    const cid = _callBgTarget();
    if (!cid) return;
    const map = _callBgMap();
    if (!map[cid]) return;
    delete map[cid];
    renderCallBgUI();
    await flushSave();
    if (typeof renderFoldSummaries === 'function') renderFoldSummaries();
    if (typeof showToast === 'function') showToast('已清除「' + (_soloName(cid) || '这位') + '」的通话背景');
  };
})();

 
 
 
 
document.addEventListener('click', e => {
  const b = e.target.closest ? e.target.closest('[data-stp]') : null;
  if (!b) return;
  const el = document.getElementById(b.dataset.stp);
  if (!el || !el.min) return;
  const min = Number(el.min), max = Number(el.max);
  const raw = String(el.value || '').trim();
  const cur = raw === '' ? NaN : Number(raw);
   
   
  const _stBook = (typeof mateBhTarget === 'function') ? (mateBhTarget().book || {}) : (data.behavior || {});
  const st = Number(_stBook[el.id]);
  const base = Number.isFinite(cur) ? cur : (Number.isFinite(st) && st > 0 ? st : min);
  el.value = Math.max(min, Math.min(max, base + (Number(b.dataset.d) || 0)));
  el.dispatchEvent(new Event('input', { bubbles: true }));
});

 
 
const _PY_PUNCT_POOL = ['pyPunctSpace', 'pyPunctDou', 'pyPunctPer', 'pyPunctEx', 'pyPunctQ', 'pyPunctEl', 'pyPunctDash', 'pyPunctNl'];
function renderPyPunctChips() {
  const box = $('#pyPunctChips');
  if (!box) return;
   
  const bh = (typeof mateBhTarget === 'function') ? (mateBhTarget().book || {}) : (data.behavior || {});
  box.classList.toggle('dis', !bh.pyEnabled || !bh.pyPunctEnabled);
  box.querySelectorAll('.punct-chip').forEach(ch => ch.classList.toggle('sel', !!bh[ch.dataset.pk]));
}
(function () {
  const box = $('#pyPunctChips');
  if (!box) return;
  box.addEventListener('click', e => {
    const ch = e.target.closest('.punct-chip');
    const _book = (typeof mateBhTarget === 'function') ? (mateBhTarget().book || {}) : null;
    if (!ch || !(_book || data.behavior)) return;
    const k = ch.dataset.pk;
    if (_PY_PUNCT_POOL.indexOf(k) < 0) return;
     
     
     
    const cur = (typeof mateBhTarget === 'function') ? (mateBhTarget().book || {}) : (data.behavior || {});
    const on = !cur[k];
    if (!on) {
      if (!_PY_PUNCT_POOL.some(x => x !== k && cur[x])) { showToast('至少保留一个拼接符号'); return; }
      if (typeof mateBhSet === 'function') mateBhSet(k, false); else data.behavior[k] = false;
    } else {
      if (typeof mateBhSet === 'function') mateBhSet(k, true); else data.behavior[k] = true;
    }
    save();
    renderPyPunctChips();
    if (typeof autoSaveToast === 'function') {
      const label = String(ch.textContent || '').trim() || '这一枚';
      autoSaveToast('已保存 · ' + (on ? '加入' : '去掉') + '「' + label + '」', true);
    }
  });
})();

 
 

 
 
 

 

 
 
 
