function _asBadgePoolArr() {
  if (!data) return [];    
  if (!data.appearance) data.appearance = {};
  if (!Array.isArray(data.appearance.asBadgePool)) data.appearance.asBadgePool = [];
  return data.appearance.asBadgePool;
}
function renderAsBadgePool() {
  const host = $('#asBadgePool');
  if (!host || !data) return;
  host.innerHTML = _asBadgePoolArr().map((it, i) =>
    '<button type="button" class="contact-chip' + (it.on ? ' active' : '') + '" data-i="' + i + '" title="' + (it.on ? '点一下取消' : '点一下点亮') + '">'
    + escapeHTML(it.s) + '</button>'
  ).join('') + '<button type="button" class="contact-chip" data-add="1" title="加一枚自己的">＋</button>';
  const row = $('#asBadgeRand');
  if (row) row.querySelectorAll('.contact-chip').forEach(c => c.classList.toggle('active', c.dataset.v === (data.appearance.asBadgeRand === false ? 'seq' : 'rand')));
}
let _asBadgeSeq = -1;    
function asBadgePick() {
  const pool = (data.appearance && Array.isArray(data.appearance.asBadgePool) ? data.appearance.asBadgePool : [])
    .filter(x => x && x.on && x.s);
  if (!pool.length) return '';
  if (data.appearance.asBadgeRand === false) {
    _asBadgeSeq = (_asBadgeSeq + 1) % pool.length;
    return pool[_asBadgeSeq].s;
  }
  return pool[Math.floor(Math.random() * pool.length)].s;
}
(() => {
  const host = $('#asBadgePool');
  if (host) host.addEventListener('click', async e => {
    const b = e.target.closest('.contact-chip');
    if (!b) return;
    if (b.dataset.add) {
      if (typeof openModal !== 'function') return;
      openModal('加一枚主动标识', '', v => {
        const s = String(v || '').trim().slice(0, 4);
        if (!s) return;
        const pool = _asBadgePoolArr();
        if (pool.some(x => x.s === s)) { showToast('这枚已经有了'); return; }
        if (pool.length >= 24) { showToast('最多 24 枚'); return; }
        pool.push({ s, on: true });
        renderAsBadgePool(); save();
        if (typeof renderFoldSummaries === 'function') renderFoldSummaries();
      }, { maxlength: 4, placeholder: '如 🌙 / ❀ / 喵' });
      return;
    }
    const pool = _asBadgePoolArr();
    const it = pool[+b.dataset.i];
    if (!it) return;
    it.on = !it.on;
    renderAsBadgePool(); save();
    if (typeof renderFoldSummaries === 'function') renderFoldSummaries();
  });
  const row = $('#asBadgeRand');
  if (row) row.addEventListener('click', e => {
    const b = e.target.closest('.contact-chip');
    if (!b) return;
    if (!data.appearance) data.appearance = {};
    data.appearance.asBadgeRand = b.dataset.v !== 'seq';
    renderAsBadgePool(); save();
  });
})();

 
 
 

 

 
 
 
 
 
 
 
 
