const DVTA_DECK_CN = { tarot: '塔罗', lenormand: '雷诺曼', both: '两种' };
 
 
const DVTA_N_CN = { free: '自由', mix: '随机混合', 1: '1 张', 3: '3 张', 5: '5 张' };
 
 
function _dvTaTyping(el) {
  if (!el) return false;
  return (typeof inputFocused === 'function') ? inputFocused(el) : (document.activeElement === el);
}
function _dvTaCid() {
  const t = (typeof _mateTarget === 'function') ? _mateTarget() : null;
  return (t && t.id) ? t.id : data.activeChat;
}
 
 
 
function renderDvTa() {
  const cid = _dvTaCid();
  const c = (typeof dvTaCfg === 'function') ? dvTaCfg(cid) : { on: false, deck: 'both', n: 'free', prob: 15, nMin: 1, nMax: 5, mixSet: ['free', 1, 3, 5] };
  const on = $('#dvTaOn');
  if (on) on.checked = !!c.on;
  document.querySelectorAll('[data-dvta-deck]').forEach(b => b.classList.toggle('active', b.dataset.dvtaDeck === c.deck));
   
  const isMix = c.n === 'mix';
  const mixOn = id => c.mixSet.some(x => String(x) === String(id));
  document.querySelectorAll('[data-dvta-n]').forEach(b => {
    const id = b.dataset.dvtaN;
    b.classList.toggle('active', isMix ? mixOn(id) : String(id) === String(c.n));
  });
  const row = $('#dvTaNRow');
  if (row) row.dataset.multi = isMix ? '1' : '0';
  const mixEl = $('#dvTaMixOn');
  if (mixEl) mixEl.checked = isMix;
  const mixHint = $('#dvTaMixHint');
  if (mixHint) mixHint.textContent = isMix
    ? '开着：这一排可多选，每轮从选中的几种里等概率挑一种'
    : '每轮从下面选中的几种里等概率挑一种';
  const p = $('#dvTaProb');
  if (p && !_dvTaTyping(p)) p.value = String(c.prob);
   
   
  const rng = $('#dvTaRange');
  if (rng) rng.hidden = !(isMix ? mixOn('free') : c.n === 'free');
  const mn = $('#dvTaNMin'), mx = $('#dvTaNMax');
  if (mn && !_dvTaTyping(mn)) mn.value = String(c.nMin);
  if (mx && !_dvTaTyping(mx)) mx.value = String(c.nMax);
   
   
  const card = $('#mateDvTaCard');
  if (card) {
    const cc = (typeof currentContact === 'function') ? currentContact() : null;
    card.hidden = !!(cc && cc.kind === 'group' && !(typeof _mateScopeOn === 'function' && _mateScopeOn()));
  }
  const sum = $('#sumDvTa');
  if (sum) {
    const nTxt = c.n === 'free' ? ('自由 ' + c.nMin + '~' + c.nMax + ' 张')
      : c.n === 'mix' ? ('随机混合 ' + c.mixSet.map(id => id === 'free' ? '自由' : id + '张').join('/'))
      : (DVTA_N_CN[c.n] || c.n);
    sum.textContent = c.on ? ('开 · ' + (DVTA_DECK_CN[c.deck] || c.deck) + ' ' + nTxt + ' · ' + c.prob + '%') : '关';
  }
}
function _dvTaWrite(patch) {
  const cid = _dvTaCid();
  if (!cid) return;
  const by = (data.dvTaBy && typeof data.dvTaBy === 'object') ? data.dvTaBy : (data.dvTaBy = {});
  const cur = (by[cid] && typeof by[cid] === 'object') ? by[cid] : (by[cid] = {});
   
  const _snap = o => JSON.stringify([o.on === true, o.deck, o.n, Number(o.prob), Number(o.nMin), Number(o.nMax),
    (Array.isArray(o.mixSet) ? o.mixSet : []).join('/')]);
  const before = _snap(cur);
  Object.assign(cur, patch);
   
   
  const cl = v => { const n = Math.round(Number(v)); return isFinite(n) ? Math.max(1, Math.min(DV_FREE_MAX, n)) : 1; };
  let lo = (cur.nMin === undefined || cur.nMin === null || cur.nMin === '') ? 1 : cl(cur.nMin);
  let hi = (cur.nMax === undefined || cur.nMax === null || cur.nMax === '') ? 5 : cl(cur.nMax);
  if ('nMin' in patch && lo > hi) hi = lo;       
  if ('nMax' in patch && hi < lo) lo = hi;       
  cur.nMin = lo; cur.nMax = hi;
   
   
   
   
  {
    const arr = Array.isArray(cur.mixSet) ? cur.mixSet : [];
    const out = ['free', 1, 3, 5].filter(id => arr.some(x => String(x) === String(id)));
    cur.mixSet = out.length ? out : ['free', 1, 3, 5];
  }
  save();
  renderDvTa();
  if (_snap(cur) !== before && typeof autoSaveToast === 'function') autoSaveToast('TA 发牌面已保存');
}
 
 
function _dvTaNumCommit(field, raw) {
  const txt = String(raw == null ? '' : raw).replace(/[^\d]/g, '');
  if (txt === '') { renderDvTa(); return; }
  const v = Math.round(Number(txt));
  if (!Number.isFinite(v)) { renderDvTa(); return; }
  _dvTaWrite({ [field]: v });
}
const _dvTaOn = $('#dvTaOn');
if (_dvTaOn) _dvTaOn.addEventListener('change', e => _dvTaWrite({ on: !!e.target.checked }));
const _dvTaDeckRow = $('#dvTaDeckRow');
if (_dvTaDeckRow) {
  _dvTaDeckRow.addEventListener('click', e => {
    const chip = e.target.closest('.contact-chip');
    if (!chip || !chip.dataset.dvtaDeck) return;
    const cur = dvTaCfg(_dvTaCid());
    if (cur.deck === chip.dataset.dvtaDeck) return;
    _dvTaWrite({ deck: chip.dataset.dvtaDeck });
  });
}
 
const _dvTaNRowEl = $('#dvTaNRow');
if (_dvTaNRowEl) {
  _dvTaNRowEl.addEventListener('click', e => {
    const chip = e.target.closest('.contact-chip');
    if (!chip || !chip.dataset.dvtaN) return;
    const id = chip.dataset.dvtaN;
    const cur = dvTaCfg(_dvTaCid());
    if (cur.n === 'mix') {
      const has = cur.mixSet.some(x => String(x) === String(id));
      if (has && cur.mixSet.length <= 1) { showToast('至少要留一种抽法'); return; }    
      const val = id === 'free' ? 'free' : Number(id);
      _dvTaWrite({ mixSet: has ? cur.mixSet.filter(x => String(x) !== String(id)) : cur.mixSet.concat([val]) });
      return;
    }
    const v = id === 'free' ? 'free' : Number(id);
    if (cur.n === v) return;
    _dvTaWrite({ n: v });
  });
}
 
 
const _dvTaMixOnEl = $('#dvTaMixOn');
if (_dvTaMixOnEl) {
  _dvTaMixOnEl.addEventListener('change', e => {
    const cur = dvTaCfg(_dvTaCid());
    if (e.target.checked) { _dvTaWrite({ n: 'mix' }); return; }
    const pick = cur.mixSet.some(x => String(x) === 'free') ? 'free' : (cur.mixSet[0] || 'free');
    _dvTaWrite({ n: pick });
  });
}
 
 
document.querySelectorAll('[data-dvta-step]').forEach(b => {
  b.addEventListener('click', () => {
    const f = b.dataset.dvtaStep;
    const cur = dvTaCfg(_dvTaCid());
    _dvTaNumCommit(f, Number(cur[f]) + (Number(b.dataset.d) || 0));
  });
});
[['dvTaNMin', 'nMin'], ['dvTaNMax', 'nMax']].forEach(([id, f]) => {
  const el = document.getElementById(id);
  if (!el) return;
   
   
   
  el.addEventListener('input', () => _dvTaNumCommit(f, el.value));
  el.addEventListener('change', () => _dvTaNumCommit(f, el.value));
  el.addEventListener('focus', () => { if (el.value) { try { el.select(); } catch (e) {} } });
});
 
 
 
const _dvTaProbEl = $('#dvTaProb');
if (_dvTaProbEl) {
  const _dvTaProbRaw = () => String(_dvTaProbEl.value || '').replace(/[^\d.]/g, '');
  const _dvTaProbCommit = () => {
    const raw = _dvTaProbRaw();
    if (raw === '') return;                                 
    const n = Math.round(Number(raw));
    if (!Number.isFinite(n)) return;                        
    _dvTaWrite({ prob: Math.max(0, Math.min(100, n)) });
  };
  _dvTaProbEl.addEventListener('input', _dvTaProbCommit);
  _dvTaProbEl.addEventListener('change', () => {
    const raw = _dvTaProbRaw();
    const n = Math.round(Number(raw));
    if (raw === '' || !Number.isFinite(n)) { renderDvTa(); return; }    
    _dvTaProbCommit();
  });
  _dvTaProbEl.addEventListener('focus', () => { if (_dvTaProbEl.value) { try { _dvTaProbEl.select(); } catch (e) {} } });
}

 
 
