const _FONT_FMT = { woff2: 'woff2', woff: 'woff', otf: 'opentype', ttf: 'truetype' };
 
 
 
 
 
 
function _fontFmtByBytes(b) {
  if (!b || b.length < 4) return '';
  if (b[0] === 0x77 && b[1] === 0x4F && b[2] === 0x46 && b[3] === 0x32) return 'woff2';       
  if (b[0] === 0x77 && b[1] === 0x4F && b[2] === 0x46 && b[3] === 0x46) return 'woff';        
  if (b[0] === 0x4F && b[1] === 0x54 && b[2] === 0x54 && b[3] === 0x4F) return 'opentype';    
  if (b[0] === 0x74 && b[1] === 0x72 && b[2] === 0x75 && b[3] === 0x65) return 'truetype';    
  if (b[0] === 0x00 && b[1] === 0x01 && b[2] === 0x00 && b[3] === 0x00) return 'truetype';    
  if (b[0] === 0x74 && b[1] === 0x74 && b[2] === 0x63 && b[3] === 0x66) return 'ttc';         
  return '';
}
 
 
 
$('#customFontUpload').onclick = () => pickFile($('#customFontUpload'), $('#customFontInput'), _importFontFile, { wait: '正在打开…', busy: '正在读取字体…' });
async function _importFontFile(file) {
  if (file.size > MAX_FILE_SIZE) { showToast('字体文件超过 5MB，装不进存档，换一个小的'); return; }
  const t0 = Date.now();
  const ext = (file.name.split('.').pop() || '').toLowerCase();
   
   
  let fmt = '';
  try { fmt = _fontFmtByBytes(new Uint8Array(await file.slice(0, 8).arrayBuffer())); } catch (e) {}
  if (!fmt) fmt = _FONT_FMT[ext] || '';
  if (fmt === 'ttc') { hideProgress(); showToast('这是字体合集（.ttc）——请先转成单个的 .ttf / .otf 再上传'); return; }
  if (!fmt) { hideProgress(); showToast('认不出这个字体格式（只支持 ttf / otf / woff / woff2），换一枚再试'); return; }
   
   
  showProgress('正在读取字体…');
  updateProgress(6, '正在读取文件…');
   
  let dataUrl = await new Promise(resolve => {
    const r = new FileReader();
    r.onprogress = ev => { if (ev.lengthComputable && ev.total) updateProgress(6 + Math.round(50 * ev.loaded / ev.total), '正在读取文件…'); };
    r.onload = () => resolve(typeof r.result === 'string' ? r.result : null);
    r.onerror = () => resolve(null);
    r.readAsDataURL(file);
  });
  if (!dataUrl) { hideProgress(); showToast('这个文件读不出来，换一枚再试'); return; }
   
   
   
  const _fmtMime = { woff2: 'font/woff2', woff: 'font/woff', opentype: 'font/otf', truetype: 'font/ttf' }[fmt];
  if (_fmtMime) dataUrl = dataUrl.replace(/^data:[^,]*,/, 'data:' + _fmtMime + ';base64,');
  updateProgress(58, '正在存进本机…');
  const s = _apSh();
  s.customFontCss = `@font-face { font-family: 'ordinal-custom'; src: url('${dataUrl}') format('${fmt}'); font-display: swap; }`;
  s.customFontName = file.name;
  applyAppearance();
  renderApSettings();
  await flushSave();
  updateProgress(100, '已载入 ' + (file.name || '字体'));
  await _pickHold(t0);                               
  await new Promise(r => setTimeout(r, 260));        
  hideProgress();
  showToast('已载入字体 ' + (file.name || '文件'));
}
$('#customFontRemove').onclick = async () => {
  const s = _apSh();
  s.customFontCss = '';
  s.customFontName = '';
  applyAppearance();
  renderApSettings();
  await flushSave();
};

 
