async function _importBubbleCss(file) {
  if (file.size > MAX_FILE_SIZE) { showToast('CSS 文件超过 5MB，装不进存档，换一个小的'); return; }
  const t0 = Date.now();
   
   
  showProgress('正在载入气泡样式…');
  updateProgress(6, '正在读取文件…');
  const text = await new Promise(resolve => {
    const r = new FileReader();
    r.onprogress = ev => { if (ev.lengthComputable && ev.total) updateProgress(6 + Math.round(48 * ev.loaded / ev.total), '正在读取文件…'); };
    r.onload = () => resolve(typeof r.result === 'string' ? r.result : null);
    r.onerror = () => resolve(null);
    r.readAsText(file);
  });
  if (!text) { hideProgress(); showToast('这个文件读不出来，换一枚再试'); return; }
  updateProgress(56, '正在应用…');
  const ta = $('#customBubbleCssText');
  if (ta) ta.value = text;
  _caSh().customBubbleCss = text.trim();
  applyAppearance();
  renderApSettings();
  await flushSave();
  if (typeof renderFoldSummaries === 'function') renderFoldSummaries();
  updateProgress(100, '已载入 ' + (file.name || 'CSS'));
  await _pickHold(t0);
  await new Promise(r => setTimeout(r, 260));
  hideProgress();
  showToast('已载入 ' + (file.name || 'CSS') + ' 并应用');
}

 
 
 
 
