async function saveMateCallNow() {
  const cid = data.activeChat || '';
  const own = _mateCallOwn(cid);
  if (!own) return false;    
  const prev = own;
  const _before = JSON.stringify(prev);
  const num = (id, min, max, pk) => {
    const raw = numInputText($(id).value);
    if (raw === '') { const cur = prev[pk]; return (typeof cur === 'number' && isFinite(cur)) ? Math.max(min, Math.min(max, cur)) : min; }
    const v = Number(raw);
    return Math.max(min, Math.min(max, Number.isFinite(v) ? v : min));
  };
  const ringMin = num('#mcRingMin', 1, 60, 'ringMin');
  const callMin = num('#mcMinLen', 1, 60, 'callMinLen');
  const iRingMin = num('#mcIncomingRingMin', 1, 120, 'incomingRingMin');
  const iMin = num('#mcIncomingMin', 1, 1440, 'incomingMin');
  const greetMin = num('#mcVoiceGreetMin', 1, 5, 'voiceGreetMin');    
  const next = {
    answerProb: num('#mcAnswerProb', 0, 100, 'answerProb'),
    rejectProb: num('#mcRejectProb', 0, 100, 'rejectProb'),
    missProb: num('#mcMissProb', 0, 100, 'missProb'),
    busyProb: num('#mcBusyProb', 0, 100, 'busyProb'),
    ringMin,
    ringMax: Math.max(ringMin, num('#mcRingMax', 1, 60, 'ringMax')),
    callMinLen: callMin,
    callMaxLen: Math.max(callMin, num('#mcMaxLen', 1, 60, 'callMaxLen')),
    incomingEnable: !!$('#mcIncomingEnable').checked,
    incomingRingMin: iRingMin,
    incomingRingMax: Math.max(iRingMin, num('#mcIncomingRingMax', 1, 120, 'incomingRingMax')),
    incomingMin: iMin,
    incomingMax: Math.max(iMin, num('#mcIncomingMax', 1, 1440, 'incomingMax')),
    incomingVideoProb: num('#mcIncomingVideoProb', 0, 100, 'incomingVideoProb'),
    noAutoHangup: !!$('#mcNoAutoHangup').checked,
    voiceGreetEnable: !!$('#mcVoiceGreet').checked,
    voiceGreetProb: num('#mcVoiceGreetProb', 0, 100, 'voiceGreetProb'),
    voiceGreetMin: greetMin,
    voiceGreetMax: Math.max(greetMin, num('#mcVoiceGreetMax', 1, 5, 'voiceGreetMax')),
     
    miniVoiceEnable: !!$('#mcMiniVoice').checked,
    miniVoiceProb: num('#mcMiniVoiceProb', 0, 100, 'miniVoiceProb')
  };
  const changed = JSON.stringify(next) !== _before;
  data.callSettingsBy[cid] = next;
   
  await flushSave();
  renderMateCall();
  return changed;
}
