(() => {
  const clampSnap = (v, lo, hi, st) => {
    const c = Math.min(hi, Math.max(lo, v));
    const k = Math.round((c - lo) / st);
    return Number(Math.min(hi, lo + k * st).toFixed(3));
  };
  const unitOf = out => {
    const m = out ? String(out.textContent || '').match(/[a-z%]+$/i) : null;
    return m ? m[0] : '';
  };
  const fire = el => {
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  Array.prototype.forEach.call(
    document.querySelectorAll('.ap-knob input[type=range], .ap-knob4 input[type=range]'),
    el => {
      const host = el.parentElement;
      const out = host ? host.querySelector('output') : null;
      const labEl = host ? host.querySelector('span') : null;
      const lab = labEl ? String(labEl.textContent || '').trim() : '';
      const lo = Number(el.min), hi = Number(el.max), st = Number(el.step) || 1;
       
      if (el.id === 'apBubRadius') {
        el.title = '双击回到「跟随气泡形状」';
        el.addEventListener('dblclick', () => {
          const b = document.getElementById('apBubRadiusRst');
          if (b) b.click();
        });
      } else if (el.id === 'apQuoteRadius') {
         
        el.title = '双击回到「跟随原样」';
        el.addEventListener('dblclick', () => {
          const b = document.getElementById('apQuoteRadiusRst');
          if (b) b.click();
        });
      } else if (el.hasAttribute('value')) {
        const def = Number(el.getAttribute('value'));
        el.title = '双击恢复默认 ' + def + unitOf(out);
        el.addEventListener('dblclick', () => {
          if (Number(el.value) === def) return;
          el.value = String(def);
          fire(el);
        });
      }
       
      if (!out) return;
      out.title = '点这里输入精确值';
      out.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        if (typeof openModal !== 'function') return;
        const unit = unitOf(out);
        openModal((lab || '数值') + ' · ' + lo + '~' + hi + (unit || ''), String(el.value), v => {
          const n = parseFloat(String(v == null ? '' : v).replace(/[^-\d.]/g, ''));
          if (!Number.isFinite(n)) return;
          const next = clampSnap(n, lo, hi, st);
          if (String(el.value) === String(next)) return;
          el.value = String(next);
          fire(el);
        }, { okText: '应用' });
        const inp = document.getElementById('appModalInput');
        if (inp) {
          inp.inputMode = 'numeric';
          try { inp.focus(); inp.select(); } catch (err) { }
        }
      });
    }
  );
})();
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 

