let _apSec = '';    
const _AP_SEC_ALL = ['layout', 'fx'];    
 
 
 
 
 
 
const _AP_SEC_BY_ID = { '#mateApCssBtn': 'bubble', '#mateLookLibBtn': 'bubble' };
 
 
 
 
function _tuneSecs() {
  try { return (TUNE_SECS && TUNE_SECS.length) ? TUNE_SECS : null; }
  catch (e) { return null; }    
}
function _apSecTag(grp) {
  const secs = _tuneSecs();
  if (!secs) return false;
  grp.querySelectorAll('.setting-card[data-fold]').forEach(card => {
    const hit = secs.find(s => s.folds.indexOf(card.dataset.fold) >= 0);
    if (hit) card.dataset.apSec = hit.k;
  });
  Object.keys(_AP_SEC_BY_ID).forEach(sel => {
    const el = grp.querySelector(sel);
    if (el) (el.closest('.setting-card') || el).dataset.apSec = _AP_SEC_BY_ID[sel];
  });
  return true;
}
function _apSecApply() {
  const grp = document.querySelector('#mateView [data-mate-grp="look"]');
  if (!grp) return;
  $$('#apJump .contact-chip').forEach(b => b.classList.toggle('active', b.dataset.apJump === _apSec));
   
  if (!_apSecTag(grp)) return;    
  const scope = _apSec ? (_AP_SEC_ALL.indexOf(_apSec) >= 0 ? 'all' : 'ta') : '';
  grp.querySelectorAll('.ap-grp').forEach(band => { band.hidden = band.dataset.apBand !== scope; });
  grp.querySelectorAll('[data-ap-sec]').forEach(el => { el.hidden = !_apSec || el.dataset.apSec !== _apSec; });
  const gAll = grp.querySelector('[data-ap-body="all"]');
  if (gAll) gAll.hidden = scope !== 'all';    
}
 
 
 
 
 
 
 
 
 
 
 
 
function _apSecSet(k) {
  const secs = _tuneSecs();
  if (!secs || !secs.some(s => s.k === k)) return;
  _apSec = k;
  _apSecApply();
  const grp = document.querySelector('#mateView [data-mate-grp="look"]');
  if (!grp) return;
  const cfg = secs.find(s => s.k === k);
  let card = null;
  (cfg.folds || []).some(f => {
    card = grp.querySelector('.setting-card[data-fold="' + f + '"]');
    return !!card;
  });
  if (card) { card.classList.add('open'); _apAccordion(card); }
}
document.addEventListener('click', e => {
  const b = e.target && e.target.closest ? e.target.closest('#apJump [data-ap-jump]') : null;
  if (!b) return;
  const k = b.dataset.apJump;
  if (_apSec === k) { _apSec = ''; _apSecApply(); }
  else _apSecSet(k);
});
function _apPrevColorFrom(el) {
  const row = el && el.closest ? el.closest('#apPrevBody .ap-prev-msg[data-apcolor]') : null;
  if (row) _apGoColor(row.dataset.apcolor);
}
document.addEventListener('click', e => _apPrevColorFrom(e.target));
document.addEventListener('keydown', e => {
  if (e.key !== 'Enter' && e.key !== ' ') return;
  const row = e.target && e.target.closest ? e.target.closest('#apPrevBody .ap-prev-msg[data-apcolor]') : null;
  if (!row) return;
  e.preventDefault();
  _apGoColor(row.dataset.apcolor);
});
document.addEventListener('click', e => {
  const hd = e.target.closest('.fold-hd');
  if (!hd) return;
  const card = hd.closest('.fold');
  if (!card) return;
  card.classList.toggle('open');
  _apAccordion(card);
});

 
 
 
 
function _apAccordion(card) {
  if (!card || !card.classList.contains('open')) return;
  const grp = card.closest('[data-mate-grp="look"]');
  if (!grp) return;
  grp.querySelectorAll('.setting-card.fold.open').forEach(c => { if (c !== card) c.classList.remove('open'); });
}

