function saveMateProfile() {
  const el = $('#nameInput');
  if (!el) return Promise.resolve();
  const c = _mateTarget();           
   
   
   
   
  if (c && c.kind !== 'group' && (typeof _mateScopeOn === 'function') && _mateScopeOn()) {
    const _g = (typeof currentContact === 'function') ? currentContact() : null;
    if (_g && _g.kind === 'group') {
      const _old = (typeof groupNickOf === 'function' ? groupNickOf(_g.id, _mateScope) : '') || chatNameOf(c) || '';
      if (typeof groupNickSet === 'function') groupNickSet(_g.id, _mateScope, el.value.trim());
      save();
       
      if (typeof renderMateScope === 'function') renderMateScope();
      if (typeof renderProfile === 'function') renderProfile();
      if (typeof resetMessageRender === 'function') resetMessageRender();
      if (typeof renderMessages === 'function') renderMessages();
      if (typeof renderChatsList === 'function') renderChatsList();
      const _now = (typeof groupNickOf === 'function' ? groupNickOf(_g.id, _mateScope) : '') || chatNameOf(c) || '';
       
      if (_now !== _old) showToast('群里的名字已保存');
      renderFoldSummaries();
      return Promise.resolve();
    }
  }
   
   
  if (c && c.kind === 'group' && !el.value.trim()) {
    showToast('群名不能空着');
    renderProfile();
    return Promise.resolve();
  }
  const name = el.value.trim() || TA_FALLBACK_NAME;
   
   
  const _oldName = c ? (c.chatName || c.name) : (data.profile && data.profile.name) || '';
   
  const _fxEl = $('#fixedNameInput');
  const _oldFixed = c ? (typeof c.fixedName === 'string' ? c.fixedName : '') : '';
  const _fx = _fxEl ? _fxEl.value.trim() : _oldFixed;
  if (c) {
     
     
     
     
     
     
    if (c.kind === 'group') { c.name = name; c.chatName = ''; }
    else c.chatName = el.value.trim();
    c.fixedName = _fx;
  }
  if (!c || c.id === 'c0') data.profile.name = name;
   
   
  const _vt = _mateVoiceTarget();
  if (!_vt.following) {
    const t = $('#mxContactTimbre');
    if (t) _vt.obj.mmTimbre = t.value.trim();
    const sb = $('#mxSpeakBtn'); if (sb) _vt.obj.mmSpeakBtn = !!sb.checked;    
     
    const tc = $('#mxTtsCards'); if (tc) _vt.obj.mmTtsCards = !!tc.checked;
    if (_vt.mem) _gvcSet(data.activeChat, _mateScope, { timbre: _vt.obj.mmTimbre, ttsCards: _vt.obj.mmTtsCards, speakBtn: _vt.obj.mmSpeakBtn });
  }
  save();
   
  if (typeof resetMessageRender === 'function') resetMessageRender();
  if (typeof renderMessages === 'function') renderMessages();
  if (typeof renderChatsList === 'function') renderChatsList();
  if (typeof updateTopbarTitle === 'function') updateTopbarTitle(document.body.dataset.view || 'chats');
   
   
   
  const _newName = c ? (c.kind === 'group' ? c.name : (c.chatName || c.name)) : name;
  if (_newName !== _oldName) showToast('昵称已保存');
  else if (_fx !== _oldFixed) showToast('固定昵称已保存');
  renderFoldSummaries();
  return Promise.resolve();
}
 
 
 
