let _fitNameCtx = null;
function fitMateName() {
  const el = $('#nameInput');
  if (!el) return;
  const cs = getComputedStyle(el);
  if (!_fitNameCtx) _fitNameCtx = document.createElement('canvas').getContext('2d');
  if (!_fitNameCtx) return;
  _fitNameCtx.font = cs.fontStyle + ' ' + cs.fontWeight + ' ' + cs.fontSize + ' ' + cs.fontFamily;
  const txt = el.value || el.placeholder || '';
  const pad = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
  const w = Math.max(48, Math.ceil(_fitNameCtx.measureText(txt).width + pad) + 2) + 'px';
  el.style.width = w;
   
   
  if (el.__ceBox) el.__ceBox.style.width = w;
}
