const UPD_SEEN_KEY = 'ordinal-upd-seen';    
 
 
const UPD_READ_KEY = 'ordinal-upd-read';

function _updSorted() {
  const raw = (typeof UPDATE_NOTES !== 'undefined' && Array.isArray(UPDATE_NOTES)) ? UPDATE_NOTES : [];
  return raw.slice().sort((a, b) => String((b && b.date) || '').localeCompare(String((a && a.date) || '')));
}

function _updWhen(u) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String((u && u.date) || ''));
  const year = m ? m[1] : '';
  const md = (u && u.label) || (m ? (+m[2]) + '.' + (+m[3]) : String((u && u.date) || ''));
  return { year, md };
}

 
function _updCardHTML(u, latest, idx, idp) {
  const when = _updWhen(u);
  const title = escapeHTML((u && u.title) || '更新');
  const kicker = escapeHTML((u && u.kicker) || '');
  const summary = escapeHTML((u && u.summary) || '');
   
  const must = !!(u && u.mustRead);
  const open = must || latest;
  const bodyId = (idp || 'updBd') + idx;
  return `<article class="upd-card${open ? ' is-open' : ''}${must ? ' is-must' : ''}${latest ? ' is-latest' : ''}" data-upd-card>
    <button type="button" class="upd-hd" data-upd-toggle aria-expanded="${open ? 'true' : 'false'}" aria-controls="${bodyId}">
      <span class="upd-when"><b>${escapeHTML(when.md)}</b><small>${escapeHTML(when.year)}</small></span>
      <span class="upd-tx">
        <span class="upd-ti">${title}${latest ? '<span class="upd-new">最新</span>' : ''}${must ? '<span class="upd-must">首次使用必读</span>' : ''}</span>
        ${kicker ? `<span class="upd-kicker">${kicker}</span>` : ''}
        ${summary ? `<span class="upd-sum">${summary}</span>` : ''}
      </span>
      <span class="upd-ar" aria-hidden="true"><svg viewBox="0 0 8 14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M1.5 1.5 6.5 7l-5 5.5"/></svg></span>
    </button>
    <div class="upd-bd" id="${bodyId}"${open ? '' : ' hidden'}>${(u && u.body) || ''}</div>
  </article>`;
}

function renderUpdatePage() {
  const box = document.getElementById('updList');
  if (!box) return;
  const list = _updSorted();
  if (!list.length) {
    box.innerHTML = '<p class="upd-empty">还没有更新公告。</p>';
    return;
  }
  box.innerHTML = list.map((u, i) => _updCardHTML(u, i === 0, i, 'updBd')).join('');
}

 

function _updSeen() { try { return localStorage.getItem(UPD_SEEN_KEY) || ''; } catch (e) { return ''; } }
function _updSeenWrite(v) { try { localStorage.setItem(UPD_SEEN_KEY, v); } catch (e) {} }

 
 
 
 
 
function _updMustOf(list) {
  const arr = list || _updSorted();
  for (let i = 0; i < arr.length; i++) if (arr[i] && arr[i].mustRead) return arr[i];
  return null;
}
 
 
let _updReadMemo = null;
function _updReadGet() {
  if (_updReadMemo === null) { try { _updReadMemo = localStorage.getItem(UPD_READ_KEY) || ''; } catch (e) { _updReadMemo = ''; } }
  return _updReadMemo;
}
function _updReadSet(v) { _updReadMemo = v; try { localStorage.setItem(UPD_READ_KEY, v); } catch (e) {} }
function _updMustDate(list) { const m = _updMustOf(list); return m ? String(m.date || '') : ''; }
function _updReadDone(list) { const d = _updMustDate(list); return !d || _updReadGet() === d; }
function _updMustAtEnd(sc, root) {
  if (!sc || !root) return false;
  const bd = root.querySelector('.upd-card.is-must .upd-bd');
  if (!bd) return true;    
  return bd.getBoundingClientRect().bottom <= sc.getBoundingClientRect().bottom + 8;
}
 
function _updReadTick(sc, root) {
  if (_updReadDone()) return;
  const d = _updMustDate();
  if (!d || !_updMustAtEnd(sc, root)) return;
  _updReadSet(d);
}

 
 
 
let _updNoteIdle = null;
let _updGateSc = null;    
 
 
 
 
 
 
let _updGateIO = null;
const UPD_GATE_HINT = '把「首次使用必读」那张读到末尾，才能关掉这一层';

 
function _updReadPin(bd) {
  if (!bd) return null;
  let pin = bd.querySelector('.upd-read-end');
  if (!pin) { pin = document.createElement('i'); pin.className = 'upd-read-end'; pin.setAttribute('aria-hidden', 'true'); bd.appendChild(pin); }
  return pin;
}
function _updGateIOTear() {
  if (_updGateIO) { try { _updGateIO.disconnect(); } catch (e) {} _updGateIO = null; }
}
 
 
 
function _updMustArm(sc) {
  _updGateIOTear();
  const bd = sc && sc.querySelector('.upd-card.is-must .upd-bd');
  const pin = bd && typeof IntersectionObserver === 'function' ? _updReadPin(bd) : null;
  if (!pin) { requestAnimationFrame(_updNoticeReadCheck); return; }
  _updGateIO = new IntersectionObserver(entries => {
    for (let i = 0; i < entries.length; i++) {
      if (!entries[i].isIntersecting) continue;
      _updNoticeReadCheck();
      if (_updReadDone()) break;    
    }
  }, { root: sc, threshold: 0 });
  _updGateIO.observe(pin);
}

function _updNoticeUnlock() {
  const ok = document.getElementById('updNoticeOk');
  const x = document.getElementById('updNoticeClose');
  const note = document.getElementById('updNoticeNote');
  if (ok) ok.disabled = false;
  if (x) x.hidden = false;
  if (note && _updNoteIdle !== null) note.textContent = _updNoteIdle;
  if (_updGateSc) { _updGateSc.removeEventListener('scroll', _updNoticeReadCheck); _updGateSc = null; }
  _updGateIOTear();    
}
function _updNoticeReadCheck() {
  const sc = document.getElementById('updNoticeList');
  if (!sc || document.getElementById('updNotice').hidden) return;
  if (_updReadDone()) { _updNoticeUnlock(); return; }
  if (!_updMustAtEnd(sc, sc)) return;
  _updReadTick(sc, sc);
  _updNoticeUnlock();
}
function _updNoticeGate(list) {
  const sc = document.getElementById('updNoticeList');
  const ok = document.getElementById('updNoticeOk');
  const x = document.getElementById('updNoticeClose');
  const note = document.getElementById('updNoticeNote');
  if (!sc || !ok) return;
  if (_updNoteIdle === null) _updNoteIdle = note ? note.textContent : '';
  if (_updReadDone(list)) { _updNoticeUnlock(); return; }
  ok.disabled = true;
  if (x) x.hidden = true;
  if (note) note.textContent = UPD_GATE_HINT;
  if (!_updGateSc) {
    _updGateSc = sc;
    sc.addEventListener('scroll', _updNoticeReadCheck, { passive: true });
  }
   
   
  _updMustArm(sc);
}
 
 
function _updNoticeClose() {
  const mask = document.getElementById('updNotice');
  if (!mask) return;
  mask.hidden = true;
  _updGateIOTear();    
  const list = _updSorted();
  if (list.length) _updSeenWrite(String(list[0].date || ''));
}

 
 
function _updNoticeBusy() {
  try { if (typeof _bkLayerBusy === 'function' && _bkLayerBusy()) return true; } catch (e) {}
  const ids = ['backupRemind', 'updateRemind'];
  for (let i = 0; i < ids.length; i++) {
    const el = document.getElementById(ids[i]);
    if (el && !el.hidden) return true;
  }
  return false;
}

 
 
let _updArmed = false;
function armUpdateNotice() {
  if (_updArmed) return;
  _updArmed = true;
   
   
  setTimeout(maybeShowUpdateNotice, Math.max(1700, 3650 - performance.now()));
}
function maybeShowUpdateNotice(tries) {
  tries = tries || 0;
  const mask = document.getElementById('updNotice');
  if (!mask || !mask.hidden) return;
  const list = _updSorted();
  const latest = list.length ? String(list[0].date || '') : '';
   
   
  if (!latest || (_updSeen() === latest && _updReadDone(list))) return;
  if ((_updNoticeBusy() || document.hidden) && tries < 20) { setTimeout(() => maybeShowUpdateNotice(tries + 1), 1500); return; }
  if (_updNoticeBusy() || document.hidden) return;
  const box = document.getElementById('updNoticeList');
  if (!box) return;
  box.innerHTML = list.map((u, i) => _updCardHTML(u, i === 0, i, 'unBd')).join('');
  const sub = document.getElementById('updNoticeSub');
  if (sub) sub.textContent = '最新：' + _updWhen(list[0]).md + ' · ' + ((list[0] && list[0].title) || '更新');
  box.scrollTop = 0;
  mask.hidden = false;
  _updNoticeGate(list);
}

 
(function () {
  const roots = [document.getElementById('updateView'), document.getElementById('updNotice')];
  roots.forEach(root => {
    if (!root) return;
    root.addEventListener('click', e => {
      const btn = (e.target && e.target.closest) ? e.target.closest('[data-upd-toggle]') : null;
      if (!btn || !root.contains(btn)) return;
      const card = btn.closest('[data-upd-card]');
      const bd = card && card.querySelector('.upd-bd');
      if (!bd) return;
       
      if (card.classList.contains('is-must')) return;
      const open = !card.classList.contains('is-open');
      card.classList.toggle('is-open', open);
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      bd.hidden = !open;
    });
  });
  const mask = document.getElementById('updNotice');
  if (mask) {
    const close = () => { _updNoticeClose(); };
    const x = document.getElementById('updNoticeClose');
    const ok = document.getElementById('updNoticeOk');
    if (x) x.addEventListener('click', close);
    if (ok) ok.addEventListener('click', close);
  }
   
   
  const page = document.querySelector('#updateView .upd-page');
  if (page) page.addEventListener('scroll', () => { _updReadTick(page, page); }, { passive: true });
})();
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 

