function _tuneTagSecs(body) {
  body.querySelectorAll('.setting-card[data-fold]').forEach(card => {
    const hit = TUNE_SECS.find(s => s.folds.indexOf(card.dataset.fold) >= 0);
    if (hit) card.dataset.tuneSec = hit.k;
  });
   
   
   
   
  ['#apResetAll'].forEach(sel => {    
    const el = body.querySelector(sel);
    if (el) (el.closest('.setting-card') || el).dataset.tuneSec = 'plan';
  });
  ['#mateApCssBtn', '#mateLookLibBtn'].forEach(sel => {
    const el = body.querySelector(sel);
    if (el) (el.closest('.setting-card') || el).dataset.tuneSec = 'bubble';
  });
}

 
function _tuneSecSet(k) {
  const cfg = TUNE_SECS.find(s => s.k === k) || TUNE_SECS[0];
  _tuneSec = cfg.k;
  _tuneLastSec = cfg.k;    
  $$('#tuneTabs .tune-tab').forEach(b => b.classList.toggle('on', b.dataset.tuneSec === cfg.k));
  const body = $('#tuneBody');
  if (body) {
    body.querySelectorAll('[data-tune-sec]').forEach(el => { el.hidden = el.dataset.tuneSec !== cfg.k; });
    body.scrollTop = 0;
  }
  const sc = $('#tuneScope');
  if (sc) sc.textContent = (_tuneName ? _tuneName + ' · ' : '') + cfg.scope;
}

 
 
function _tuneFoldReset() {
  const p = _tunePanel();
  const main = $('#tuneMain');
  const fb = $('#tuneFold');
  if (main) main.hidden = false;
  if (fb) fb.textContent = '收起';
  if (p) p.classList.remove('tune-folded');
}

 
 
 
