  return `<div class="taq-row own${off ? ' off' : ''}" data-taq-edit="${escapeHTML(c.id)}"><div class="taq-tx">${body}</div>
    <div class="taq-acts">${_taqSw('data-taq-off="' + escapeHTML(c.id) + '"', off)}</div></div>`;
