function _taqToggleScope(scope) { if (_taqEdit) { _taqEdit.scope = scope === 'own' ? 'own' : 'public'; _taqPaintScope(); } }
function _taqPickOwner(cid) { if (_taqEdit) { _taqEdit.cid = cid || ''; _taqPaintScope(); } }

 
