  if (!manual) {
    const sayInv = _plPickInvSay(cid, _plSayPool(t ? PL_SAY_NAMES.invSay : PL_SAY_NAMES.invSayAny));
    if (sayInv) _plChatNote(cid, { id: nextId(), from: 'partner', text: sayInv });
  }
